def allowed_file(filename):
    return '.' in filename and filename.rsplit('.', 1)[1].lower() in app.config['ALLOWED_EXTENSIONS']


@app.route('/save-currency-settings', methods=['POST'])
def save_currency_settings():
    with get_db() as (cursor, connection):
        try:
            user_uuid = session.get('user_uuid')
            table_name = session.get('table_name')
            empid = session.get('empid')

            if not user_uuid:
                return jsonify({"success": False, "message": "Not authorized"}), 401
            
            table_name = session.get('table_name')
            data = request.get_json()
            
            # Extract settings
            base_currency = data.get('baseCurrency')
            split_enabled = data.get('splitEnabled', False)
            
            # Extract split config if enabled
            usd_percent = None
            zwg_percent = None
            exchange_rate = None
            
            if split_enabled and data.get('splitConfig'):
                split_config = data.get('splitConfig')
                usd_percent = split_config.get('usdPercent')
                zwg_percent = split_config.get('zwgPercent')
                exchange_rate = split_config.get('exchangeRate')
            
            # Update EVERY ROW in the employee table with the new currency settings
            cursor.execute(f"""
                UPDATE {table_name} 
                SET currency = %s,
                    usd_percent = %s,
                    zwg_percent = %s,
                    exchange_rate = %s
            """, (
                base_currency,
                usd_percent if split_enabled else None,
                zwg_percent if split_enabled else None,
                exchange_rate if split_enabled else None
            ))
            
            connection.commit()
            
            return jsonify({
                'success': True,
                'message': 'Currency configuration saved successfully!'
            })
            
        except Exception as e:
            connection.rollback()
            print(f"Error saving currency settings: {str(e)}")
            return jsonify({
                'success': False,
                'message': str(e)
            }), 500

@app.route('/get-currency-settings', methods=['GET'])
def get_currency_settings():
    with get_db() as (cursor, connection):
        try:

            user_uuid = session.get('user_uuid')
            table_name = session.get('table_name')
            empid = session.get('empid')

            if not user_uuid:
                return jsonify({"success": False, "message": "Not authorized"}), 401
            
            # Get settings for this user
            cursor.execute(f"""
                SELECT currency, usd_percent, zwg_percent, exchange_rate 
                FROM {table_name} 
                WHERE user_uuid = %s 
                ORDER BY id DESC
            """, (user_uuid,))
            
            settings = cursor.fetchone()
            
            if settings:
                return jsonify({
                    'success': True,
                    'data': {
                        'baseCurrency': settings[0],
                        'splitEnabled': settings[1] is not None and settings[2] is not None,
                        'splitConfig': {
                            'usdPercent': float(settings[1]) if settings[1] is not None else 0,
                            'zwgPercent': float(settings[2]) if settings[2] is not None else 0,
                            'exchangeRate': float(settings[3]) if settings[3] is not None else 0
                        } if settings[1] is not None else None
                    }
                })
            else:
                # Return default settings if none exist
                return jsonify({
                    'success': True,
                    'data': {
                        'baseCurrency': 'USD',
                        'splitEnabled': False,
                        'splitConfig': None
                    }
                })
                
        except Exception as e:
            print(f"Error getting currency settings: {str(e)}")
            return jsonify({
                'success': False,
                'message': str(e)
            }), 500

@app.route('/upload-excel', methods=['POST'])
def upload_excel():

    with get_db() as (cursor, connection):

        user_uuid = session.get('user_uuid')
        if user_uuid:

            table_name = session.get('table_name')
            empid = session.get('empid')

            if 'file' not in request.files:
                return jsonify({"status": "error", "message": "No file part"}), 400
            
            file = request.files['file']
            
            if file.filename == '':
                return jsonify({"status": "error", "message": "No selected file"}), 400
            
            if file and allowed_file(file.filename):

                df = pd.read_excel(file, usecols=range(8))
                df = check_existing_data(df, table_name)
                df = df.dropna(subset=['FirstName'])

                print(df)

                if len(df) > 0:

                    for index, row in df.iterrows():
                        first_name = row['FirstName']
                        surname = row['Surname']

                        if pd.notna(row['WhatsApp']):
                            whatsapp_raw = str(int(float(row['WhatsApp']))).replace(" ", "")
                        else:
                            print("NaN skipped")

                        whatsapp = whatsapp_raw[-9:] if len(whatsapp_raw) >= 9 else whatsapp_raw
                        email = row['Email']
                        role = row['Role']
                        department = row['Department']
                        current_leave_days_balance = row['Current Leave Days Balance']
                        monthly_accumulation = row['Monthly Leave Days Accumulation']

                        cursor.execute(f"""
                            INSERT INTO {table_name} (firstname, surname, whatsapp, email, role, department, currentleavedaysbalance, monthlyaccumulation)
                            VALUES (%s, %s, %s, %s, %s, %s, %s, %s)
                        """, (first_name, surname, whatsapp, email, role, department, current_leave_days_balance, monthly_accumulation))
                    
                    connection.commit()

                return redirect(url_for('Dashboard'))

        else:
            return redirect(url_for('landingpage')) 



@app.route('/upload-excel-payroll', methods=['POST'])
def upload_payroll():
    with get_db() as (cursor, connection):
        user_uuid = session.get('user_uuid')
        if user_uuid:

            table_name = session.get('table_name')
            
            if 'file-payroll' not in request.files:
                return jsonify({"status": "error", "message": "No file part"}), 400
            
            file = request.files['file-payroll']
            
            if file.filename == '':
                return jsonify({"status": "error", "message": "No selected file"}), 400
            
            if file and allowed_file(file.filename):
                
                df = pd.read_excel(file)
                
                # Ensure required columns exist
                required_columns = ['Employee ID', 'Account Holder First Name', 'Account Holder Surname', 
                                  'Bank Name', 'Account Number', 'Branch', 'Branch Code', 
                                  'Basic Salary in Base Currency', 'Base Currency']
                
                if not all(col in df.columns for col in required_columns):
                    return jsonify({"status": "error", "message": "Missing required columns"}), 400
                
                success_count = 0
                error_count = 0
                
                for index, row in df.iterrows():
                    try:
                        employee_id = row['Employee ID']
                        
                        # Skip if Employee ID is missing
                        if pd.isna(employee_id):
                            error_count += 1
                            continue
                        
                        # Convert Employee ID to int
                        employee_id = int(float(employee_id))
                        
                        # Check if employee exists
                        cursor.execute(f"SELECT id FROM {table_name} WHERE id = %s", (employee_id,))
                        if not cursor.fetchone():
                            print(f"Employee ID {employee_id} not found")
                            error_count += 1
                            continue
                        
                        # Update employee payroll details with all columns
                        cursor.execute(f"""
                            UPDATE {table_name} 
                            SET 
                                bank = %s,
                                accnumber = %s,
                                branch = %s,
                                branchcode = %s,
                                c8 = %s,
                                currency = %s
                            WHERE id = %s
                        """, (
                            row['Bank Name'] if pd.notna(row['Bank Name']) else None,
                            str(row['Account Number']) if pd.notna(row['Account Number']) else None,
                            row['Branch'] if pd.notna(row['Branch']) else None,
                            str(row['Branch Code']) if pd.notna(row['Branch Code']) else None,
                            row['Basic Salary in Base Currency'] if pd.notna(row['Basic Salary in Base Currency']) else None,
                            row['Base Currency'] if pd.notna(row['Base Currency']) else None,
                            employee_id
                        ))
                        
                        success_count += 1
                        
                    except Exception as e:
                        print(f"Error processing row {index}: {str(e)}")
                        error_count += 1
                        continue
                
                connection.commit()
                
                return jsonify({
                    "status": "success", 
                    "message": f"Payroll upload complete. Success: {success_count}, Errors: {error_count}"
                }), 200
        
        else:
            return jsonify({"status": "error", "message": "Not authorized"}), 401

@app.route('/download-excel-template-add-employees')
def download_excel_template_add_employees():

    with get_db() as (cursor, connection):

        user_uuid = session.get('user_uuid')
        if not user_uuid:
            return redirect(url_for('landingpage'))
        

        try:

            table_name = session.get('table_name')
            company_name = table_name.replace("main", "")

            wb = openpyxl.Workbook()
            ws = wb.active
            ws.title = "Employee Details"

            # Add headers
            headers = [
                "FirstName", "Surname", "WhatsApp", "Email", 
                "Role", "Department", 
                "Current Leave Days Balance", "Monthly Leave Days Accumulation"
            ]
            ws.append(headers)

            # Style headers
            dark_blue = "003366"
            white = "FFFFFF"
            for col in range(1, len(headers) + 1):
                cell = ws.cell(row=1, column=col)
                cell.fill = PatternFill(start_color=dark_blue, end_color=dark_blue, fill_type="solid")
                cell.font = Font(color=white, bold=True)

            # Role dropdown (inline, short list)
            role_dv = DataValidation(type="list", formula1='"Administrator,Ordinary User"', allow_blank=False)
            ws.add_data_validation(role_dv)
            for row in range(2, 500):
                role_dv.add(ws[f"E{row}"])

            # Department options (long list) - write to column Z
            departments = [
                "Human Resources and Administration",
                "Finance and Accounting",
                "Sales and Marketing",
                "Sales and Distribution",
                "Workshop and Maintenance",
                "Operations and Production",
                "Procurement and Purchasing",
                "Customer Service and Support",
                "IT and Digital Infrastructure",
                "Risk Management",
                "Legal and Compliance",
                "Health, Safety and Environment",
                "Research, Analytics and Reporting"
            ]

            for i, dept in enumerate(departments, start=1):
                ws[f"Z{i}"] = dept

            # Department dropdown using cell range
            dept_dv = DataValidation(type="list", formula1="=$Z$1:$Z$13", allow_blank=False)
            ws.add_data_validation(dept_dv)
            for row in range(2, 500):
                dept_dv.add(ws[f"F{row}"])

            # Hide the reference column
            ws.column_dimensions['Z'].hidden = True

            # Save workbook to memory stream
            output = io.BytesIO()
            wb.save(output)
            output.seek(0)

            filename = f"{company_name.strip()}_Employee_Details_Template.xlsx"
            return send_file(output, download_name=filename, as_attachment=True)
        
        except Error as e:
            print(e)

            return redirect(url_for('Dashboard'))


@app.route('/download-excel-template-payroll-employees')
def download_excel_template_payroll_employees():
    with get_db() as (cursor, connection):
        user_uuid = session.get('user_uuid')
        if not user_uuid:
            return redirect(url_for('landingpage'))
        
        try:
            table_name = session.get('table_name')
            company_name = table_name.replace("main", "")
            
            # Fetch column names from the table
            cursor.execute(f"""
                SELECT column_name 
                FROM information_schema.columns 
                WHERE table_name = '{table_name}'
            """)
            
            columns_result = cursor.fetchall()
            
            # Filter for specific columns you want
            desired_columns = [
                'id', 'firstname', 'surname', 'bank', 'accnumber', 'branch', 
                'branchcode', 'c8', 'currency'
            ]
            
            # Create a mapping for user-friendly headers
            column_headers = {
                'id': 'Employee ID',
                'firstname': 'Account Holder First Name',
                'surname': 'Account Holder Surname',
                'bank': 'Bank Name',
                'accnumber': 'Account Number',
                'branch': 'Branch',
                'branchcode': 'Branch Code',
                'c8': 'Basic Salary in Base Currency',
                'currency': 'Base Currency'
            }
            
            # Determine which columns exist in the table
            existing_columns = []
            headers = []
            for col in desired_columns:
                # Check if this column exists in the database
                column_exists = any(col_tuple[0] == col for col_tuple in columns_result)
                
                if column_exists:
                    existing_columns.append(col)
                    headers.append(column_headers.get(col, col))


            
            if not existing_columns:
                return "No relevant columns found in the table", 400
            
            # Build query with only existing columns
            columns_str = ", ".join([f'"{col}"' for col in existing_columns])
            query = f'SELECT {columns_str} FROM "{table_name}"'
            
            cursor.execute(query)
            employees = cursor.fetchall()
            
            # Create Excel workbook
            wb = openpyxl.Workbook()
            ws = wb.active
            ws.title = "Employee Payroll Data"
            
            # Add headers
            ws.append(headers)
            
            # Style headers
            dark_blue = "003366"
            white = "FFFFFF"
            for col in range(1, len(headers) + 1):
                cell = ws.cell(row=1, column=col)
                cell.fill = PatternFill(start_color=dark_blue, end_color=dark_blue, fill_type="solid")
                cell.font = Font(color=white, bold=True)
            
            # Add data rows
            for employee in employees:
                ws.append(employee)
            
            # Auto-adjust column widths
            for column in ws.columns:
                max_length = 0
                column_letter = column[0].column_letter
                for cell in column:
                    try:
                        if len(str(cell.value)) > max_length:
                            max_length = len(str(cell.value))
                    except:
                        pass
                adjusted_width = min(max_length + 2, 50)
                ws.column_dimensions[column_letter].width = adjusted_width
            
            # Add freeze pane for headers
            ws.freeze_panes = "A2"
            
            # Save to memory stream
            output = io.BytesIO()
            wb.save(output)
            output.seek(0)
            
            filename = f"{company_name.strip()}_Employee_Payroll_Data.xlsx"
            return send_file(
                output, 
                download_name=filename, 
                as_attachment=True,
                mimetype='application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            )
        
        except Error as e:
            print(f"Database error: {e}")
            return redirect(url_for('Dashboard'))
        except Exception as e:
            print(f"General error: {e}")
            return redirect(url_for('Dashboard'))


