COMPANY_SYSTEM_NAME = "Brilliant Chemicals"
COMPANY_SYSTEM_ADMIN_ROLE = "Administrator"

# The company WhatsApp channel. Numbers that belong to employees keep the
# existing LMS assistant; every other number on this channel is treated as a
# customer enquiry and is routed into the CRM inbox. Comma-separated override:
# COMPANY_SYSTEM_WA_NUMBERS="263789339777,263790060968"
COMPANY_SYSTEM_WA_NUMBERS = {
    number.strip()
    for number in os.getenv("COMPANY_SYSTEM_WA_NUMBERS", "263789339777").split(",")
    if number.strip()
}


def company_system_channel_label():
    """The company WhatsApp number shown to users."""
    return sorted(COMPANY_SYSTEM_WA_NUMBERS)[0] if COMPANY_SYSTEM_WA_NUMBERS else ""

_wa_channels = {}
_crm_tables_ready = False

_column_cache = {}


def identifier_has_column(cursor, table_name, column_name):
    """True when `table_name` really has `column_name`.

    The customer channel discovers employee tables by looking for a `password`
    column, which also matches tables that have no `whatsapp` column at all.
    Querying one of those raises, so every candidate is checked first. Results
    are cached because this runs per inbound WhatsApp message.
    """
    key = (str(table_name), str(column_name))
    if key in _column_cache:
        return _column_cache[key]
    try:
        cursor.execute("""
            SELECT 1 FROM information_schema.columns
            WHERE table_schema = 'public' AND table_name = %s AND column_name = %s
            LIMIT 1
        """, (str(table_name), str(column_name)))
        present = cursor.fetchone() is not None
    except Exception as e:
        print(f"column check failed for {table_name}.{column_name}: {e}")
        # Do not cache a failure: a transient database problem must not make a
        # table permanently invisible to the employee lookup.
        return False
    _column_cache[key] = present
    return present

# ------------------------------------------------------------------ web push --
# Staff devices subscribe once and are then alerted by the server whenever a
# customer asks for a person, even if the CRM tab is closed. The VAPID key pair
# is supplied by the deployment environment; nothing is hard-coded here, because
# the private key is what authorises a push to every subscribed device.
VAPID_PUBLIC_KEY = (os.getenv("VAPID_PUBLIC_KEY") or "").strip()
VAPID_PRIVATE_KEY = (os.getenv("VAPID_PRIVATE_KEY") or "").strip()
VAPID_SUBJECT = (os.getenv("VAPID_SUBJECT") or "mailto:admin@brilliantchemicals.co.zw").strip()

_push_ready = False
_push_lib = None
_push_tables_ready = False


def push_configured():
    """True when the deployment has a usable VAPID key pair."""
    return bool(VAPID_PUBLIC_KEY and VAPID_PRIVATE_KEY)


def _push_library():
    """Import pywebpush lazily so a missing package never breaks startup."""
    global _push_lib, _push_ready
    if _push_ready:
        return _push_lib
    _push_ready = True
    try:
        from pywebpush import webpush, WebPushException
        _push_lib = {"webpush": webpush, "WebPushException": WebPushException}
    except Exception as e:
        print(f"web push unavailable: {e}")
        _push_lib = None
    return _push_lib


def ensure_push_tables():
    """Create the push subscription table the first time it is needed."""
    global _push_tables_ready
    if _push_tables_ready:
        return
    try:
        with get_db() as (cursor, connection):
            cursor.execute("""
                CREATE TABLE IF NOT EXISTS push_subscriptions (
                    id SERIAL PRIMARY KEY,
                    endpoint TEXT UNIQUE,
                    p256dh TEXT,
                    auth TEXT,
                    user_email VARCHAR(200),
                    user_name VARCHAR(200),
                    user_agent VARCHAR(300),
                    last_seen_at TIMESTAMP DEFAULT NOW(),
                    created_at TIMESTAMP DEFAULT NOW()
                );
            """)
            connection.commit()
        _push_tables_ready = True
    except Exception as e:
        print(f"push table error: {e}")


def push_save_subscription(subscription, user=None):
    """Store or refresh one device subscription. Returns True when saved."""
    if not isinstance(subscription, dict):
        return False
    endpoint = (subscription.get("endpoint") or "").strip()
    keys = subscription.get("keys") or {}
    p256dh = (keys.get("p256dh") or "").strip()
    auth = (keys.get("auth") or "").strip()
    if not (endpoint and p256dh and auth):
        return False
    user = user or {}
    try:
        ensure_push_tables()
        with get_db() as (cursor, connection):
            # A device that subscribes again gets refreshed rather than duplicated,
            # so the endpoint stays unique and staff changes are picked up.
            cursor.execute("""
                INSERT INTO push_subscriptions (endpoint, p256dh, auth, user_email,
                                                user_name, user_agent, last_seen_at)
                VALUES (%s, %s, %s, %s, %s, %s, NOW())
                ON CONFLICT (endpoint) DO UPDATE SET
                    p256dh = EXCLUDED.p256dh,
                    auth = EXCLUDED.auth,
                    user_email = COALESCE(EXCLUDED.user_email, push_subscriptions.user_email),
                    user_name = COALESCE(EXCLUDED.user_name, push_subscriptions.user_name),
                    user_agent = COALESCE(EXCLUDED.user_agent, push_subscriptions.user_agent),
                    last_seen_at = NOW()
            """, (endpoint, p256dh, auth,
                  (user.get("email") or "").strip() or None,
                  f"{user.get('firstname', '')} {user.get('surname', '')}".strip() or None,
                  (subscription.get("user_agent") or "")[:300] or None))
            connection.commit()
        return True
    except Exception as e:
        print(f"push subscribe error: {e}")
        return False


def push_remove_subscription(endpoint):
    """Forget a device, e.g. when the browser reports the subscription is gone."""
    endpoint = (endpoint or "").strip()
    if not endpoint:
        return False
    try:
        ensure_push_tables()
        with get_db() as (cursor, connection):
            cursor.execute("DELETE FROM push_subscriptions WHERE endpoint = %s", (endpoint,))
            connection.commit()
        return True
    except Exception as e:
        print(f"push unsubscribe error: {e}")
        return False


def _push_list_subscriptions():
    try:
        ensure_push_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT endpoint, p256dh, auth FROM push_subscriptions")
            return cursor.fetchall()
    except Exception as e:
        print(f"push list error: {e}")
        return []


def push_notify_staff(title, body, url="/portal/crm", tag="bc-crm"):
    """Alert every subscribed staff device.

    Returns (sent, failed). Dead subscriptions are pruned so a device that has
    been wiped stops being retried forever. Never raises: a notification failing
    must not take down the webhook that triggered it.
    """
    library = _push_library()
    if library is None or not push_configured():
        return 0, 0
    payload = json.dumps({"title": title, "body": body, "url": url, "tag": tag})
    sent = 0
    failed = 0
    gone = []
    for endpoint, p256dh, auth in _push_list_subscriptions():
        subscription = {"endpoint": endpoint, "keys": {"p256dh": p256dh, "auth": auth}}
        try:
            library["webpush"](
                subscription_info=subscription,
                data=payload,
                vapid_private_key=VAPID_PRIVATE_KEY,
                vapid_claims={"sub": VAPID_SUBJECT},
                timeout=10,
            )
            sent += 1
        except library["WebPushException"] as e:
            status = getattr(getattr(e, "response", None), "status_code", None)
            if status in (404, 410):
                # The browser threw the subscription away; stop retrying it.
                gone.append(endpoint)
            else:
                failed += 1
        except Exception as e:
            print(f"push send error: {e}")
            failed += 1
    for endpoint in gone:
        push_remove_subscription(endpoint)
    if sent or failed or gone:
        print(f"push notify: {sent} sent, {failed} failed, {len(gone)} pruned")
    return sent, len(gone) + failed


def register_wa_channel(display_phone_number, access_token, phone_number_id):
    """Remember the Meta credentials a webhook request arrived on.

    The reply is sent from a later request that may be served by another worker,
    so the credentials are written to the database and read back by whoever
    needs to send.
    """
    try:
        if display_phone_number and access_token and phone_number_id:
            _wa_channels[str(display_phone_number)] = {
                "token": access_token,
                "phone_id": str(phone_number_id),
            }
            # The table may not exist yet on a fresh deployment, and losing the
            # credentials here is what makes agent replies undeliverable later.
            ensure_crm_tables()
            with get_db() as (cursor, connection):
                cursor.execute("""
                    INSERT INTO whatsapp_channels
                        (display_phone_number, phone_number_id, access_token, updated_at)
                    VALUES (%s, %s, %s, NOW())
                    ON CONFLICT (display_phone_number) DO UPDATE
                        SET phone_number_id = EXCLUDED.phone_number_id,
                            access_token = EXCLUDED.access_token,
                            updated_at = NOW()
                """, (str(display_phone_number), str(phone_number_id), access_token))
                connection.commit()
    except Exception as e:
        print(f"register_wa_channel failed: {e}")


def wa_outbound_credentials(channel=None):
    """The Meta credentials to send from, or None.

    The environment is checked first because it is the deliberate override an
    operator sets; failing that the channels remembered from webhooks are used,
    so a worker that has never received one can still deliver a reply.
    """
    token = os.getenv("WHATSAPP_ACCESS_TOKEN")
    phone_id = os.getenv("WHATSAPP_PHONE_NUMBER_ID")
    if token and phone_id:
        return {"token": token, "phone_id": str(phone_id)}
    creds = _wa_channels.get(str(channel)) if channel else None
    if creds is None:
        # Another worker may have handled every webhook so far.
        wa_load_channels()
        creds = _wa_channels.get(str(channel)) if channel else None
    if creds is None and _wa_channels:
        creds = list(_wa_channels.values())[-1]
    return creds


def wa_load_channels():
    """Reload the remembered channels from the database.

    Returns the number of channels held. The read is cheap and the result is
    cached in this process, so it is called whenever a send finds nothing.
    """
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT display_phone_number, phone_number_id, access_token
                FROM whatsapp_channels
            """)
            for row in cursor.fetchall():
                if row[1] and row[2]:
                    _wa_channels[str(row[0])] = {"token": row[2], "phone_id": str(row[1])}
    except Exception as e:
        print(f"channel load error: {e}")
    return len(_wa_channels)


def ensure_crm_tables():
    """Create the CRM inbox tables the first time they are needed."""
    global _crm_tables_ready
    if _crm_tables_ready:
        return
    with get_db() as (cursor, connection):
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS whatsapp_chats (
                id SERIAL PRIMARY KEY,
                wa_number VARCHAR(32) UNIQUE,
                display_name VARCHAR(200),
                company_reg VARCHAR(120),
                channel VARCHAR(32),
                status VARCHAR(20) DEFAULT 'bot',
                unattended BOOLEAN DEFAULT TRUE,
                handoff_reason VARCHAR(200),
                unread_count INTEGER DEFAULT 0,
                last_message TEXT,
                last_message_at TIMESTAMP,
                last_message_direction VARCHAR(12),
                assigned_to VARCHAR(120),
                is_staff BOOLEAN DEFAULT FALSE,
                created_at TIMESTAMP DEFAULT NOW(),
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS whatsapp_messages (
                id SERIAL PRIMARY KEY,
                chat_id INTEGER,
                wa_number VARCHAR(32),
                direction VARCHAR(12),
                sender VARCHAR(24),
                message_type VARCHAR(24),
                body TEXT,
                delivered BOOLEAN,
                created_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # The Meta credentials an outbound reply needs. They arrive on the
        # webhook request, but the reply is sent from a different request that
        # may land on another worker, so they are kept in the database rather
        # than only in this process.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS whatsapp_channels (
                display_phone_number VARCHAR(40) PRIMARY KEY,
                phone_number_id VARCHAR(40),
                access_token TEXT,
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        cursor.execute("CREATE INDEX IF NOT EXISTS whatsapp_messages_chat_idx ON whatsapp_messages (chat_id, id);")
        # Bring installs created before these columns existed up to date.
        cursor.execute("ALTER TABLE whatsapp_messages ADD COLUMN IF NOT EXISTS delivered BOOLEAN;")
        # The name a reply went out under, so the thread can show which member of
        # staff answered instead of a generic "Agent".
        cursor.execute("ALTER TABLE whatsapp_messages ADD COLUMN IF NOT EXISTS display_name VARCHAR(200);")
        cursor.execute("ALTER TABLE whatsapp_chats ADD COLUMN IF NOT EXISTS is_staff BOOLEAN DEFAULT FALSE;")
        cursor.execute("UPDATE whatsapp_chats SET is_staff = FALSE WHERE is_staff IS NULL;")
        cursor.execute("""
            ALTER TABLE whatsapp_chats ADD COLUMN IF NOT EXISTS wa_profile_name VARCHAR(200);
        """)
        connection.commit()
    _crm_tables_ready = True


def crm_record_message(wa_number, direction, sender, body, message_type="text",
                       display_name=None, company_reg=None, escalate=False,
                       reason=None, channel=None, delivered=None, is_staff=False,
                       sender_name=None):
    """Persist one WhatsApp message and keep the CRM chat index in sync.

    Staff conversations are stored too so the inbox is a complete record of the
    channel, but they are flagged and never counted as unattended enquiries.

    `sender_name` names whoever sent this specific message (the staff member who
    replied), which is kept per-message and never renames the chat.
    """
    if not wa_number or not body:
        return None
    wa_number = str(wa_number)[-15:]
    is_staff = bool(is_staff)
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT id FROM whatsapp_chats WHERE wa_number = %s", (wa_number,))
            row = cursor.fetchone()

            if row is None:
                cursor.execute("""
                    INSERT INTO whatsapp_chats (wa_number, display_name, company_reg, channel,
                                                status, unattended, handoff_reason, unread_count,
                                                last_message, last_message_at, last_message_direction,
                                                is_staff, wa_profile_name, created_at, updated_at)
                    VALUES (%s, %s, %s, %s, 'bot', %s, %s, %s, %s, NOW(), %s, %s, %s, NOW(), NOW())
                    RETURNING id
                """, (wa_number, display_name, company_reg, channel,
                      bool(escalate) and not is_staff, reason,
                      0 if is_staff else (1 if direction == "inbound" else 0),
                      body, direction, is_staff, display_name))
                chat_id = cursor.fetchone()[0]
            else:
                chat_id = row[0]
                if direction == "inbound":
                    cursor.execute("""
                        UPDATE whatsapp_chats
                        SET unread_count = CASE WHEN %s THEN unread_count ELSE unread_count + 1 END,
                            unattended = CASE WHEN %s THEN TRUE WHEN %s THEN FALSE ELSE unattended END,
                            handoff_reason = COALESCE(%s, handoff_reason),
                            display_name = COALESCE(%s, display_name),
                            wa_profile_name = COALESCE(%s, wa_profile_name),
                            company_reg = COALESCE(%s, company_reg),
                            channel = COALESCE(%s, channel),
                            is_staff = is_staff OR %s,
                            last_message = %s,
                            last_message_at = NOW(),
                            last_message_direction = 'inbound',
                            updated_at = NOW()
                        WHERE id = %s
                    """, (is_staff, bool(escalate) and not is_staff, is_staff,
                          None if is_staff else reason, display_name, display_name, company_reg,
                          channel, is_staff, body, chat_id))
                elif sender == "agent":
                    cursor.execute("""
                        UPDATE whatsapp_chats
                        SET unread_count = 0, unattended = FALSE,
                            last_message = %s, last_message_at = NOW(),
                            last_message_direction = 'outbound', updated_at = NOW()
                        WHERE id = %s
                    """, (body, chat_id))
                else:
                    cursor.execute("""
                        UPDATE whatsapp_chats
                        SET last_message = %s, last_message_at = NOW(),
                            last_message_direction = 'outbound', updated_at = NOW()
                        WHERE id = %s
                    """, (body, chat_id))

            cursor.execute("""
                INSERT INTO whatsapp_messages (chat_id, wa_number, direction, sender, message_type,
                                               body, delivered, display_name, created_at)
                VALUES (%s, %s, %s, %s, %s, %s, %s, %s, NOW())
            """, (chat_id, wa_number, direction, sender, message_type, body, delivered,
                  sender_name))
            connection.commit()
        return chat_id
    except Exception as e:
        print(f"CRM log error: {e}")
        return None


def crm_best_display_name(wa_number):
    """The best name known for a WhatsApp number.

    Prefers the customer's WhatsApp profile name, falling back to whatever the
    chat was first titled with. Used so an order or analytics row shows a real
    name even when the buyer never typed one at checkout.
    """
    if not wa_number:
        return None
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT COALESCE(wa_profile_name, display_name)
                FROM whatsapp_chats WHERE wa_number = %s
            """, (str(wa_number)[-15:],))
            row = cursor.fetchone()
        return (row[0] or None) if row else None
    except Exception as e:
        print(f"display name lookup error: {e}")
        return None


def crm_chat_id(wa_number, display_name=None, channel=None, is_staff=False):
    """Resolve (creating when needed) the CRM chat row for a number."""
    if not wa_number:
        return None
    wa_number = str(wa_number)[-15:]
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT id FROM whatsapp_chats WHERE wa_number = %s", (wa_number,))
            row = cursor.fetchone()
            if row:
                return row[0]
            cursor.execute("""
                INSERT INTO whatsapp_chats (wa_number, display_name, company_reg, channel,
                                            status, unattended, unread_count, is_staff,
                                            created_at, updated_at)
                VALUES (%s, %s, %s, %s, 'bot', FALSE, 0, %s, NOW(), NOW())
                ON CONFLICT (wa_number) DO NOTHING
                RETURNING id
            """, (wa_number, display_name, COMPANY_SYSTEM_PREFIX, channel, bool(is_staff)))
            row = cursor.fetchone()
            if row is None:
                cursor.execute("SELECT id FROM whatsapp_chats WHERE wa_number = %s", (wa_number,))
                row = cursor.fetchone()
            connection.commit()
            return row[0] if row else None
    except Exception as e:
        print(f"CRM chat lookup error: {e}")
        return None


def crm_set_chat_mode(chat_id, mode, assigned_to=None):
    """Switch a chat between the assistant and a human agent."""
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            if mode == "human":
                cursor.execute("""
                    UPDATE whatsapp_chats
                    SET status = 'human', unattended = FALSE, assigned_to = %s,
                        handoff_reason = NULL, unread_count = 0, updated_at = NOW()
                    WHERE id = %s
                """, (assigned_to, chat_id))
            elif mode == "escalated":
                cursor.execute("""
                    UPDATE whatsapp_chats
                    SET status = 'escalated', unattended = TRUE, updated_at = NOW()
                    WHERE id = %s
                """, (chat_id,))
            elif mode == "closed":
                cursor.execute("""
                    UPDATE whatsapp_chats
                    SET status = 'closed', unattended = FALSE, updated_at = NOW()
                    WHERE id = %s
                """, (chat_id,))
            else:
                cursor.execute("""
                    UPDATE whatsapp_chats
                    SET status = 'bot', assigned_to = NULL, updated_at = NOW()
                    WHERE id = %s
                """, (chat_id,))
            connection.commit()
        return True
    except Exception as e:
        print(f"CRM mode error: {e}")
        return False


def crm_chat_is_human(wa_number):
    """True when a human agent has taken the conversation over."""
    try:
        ensure_crm_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT status FROM whatsapp_chats WHERE wa_number = %s", (str(wa_number)[-15:],))
            row = cursor.fetchone()
        return bool(row and row[0] == "human")
    except Exception as e:
        print(f"CRM lookup error: {e}")
        return False


# Meta error codes that mean "you cannot message this customer right now".
# 131047 is the 24-hour customer-service window expiring; the others are the
# same condition phrased for template or re-engagement failures.
WA_WINDOW_ERROR_CODES = {131047, 131026, 131051}


def wa_error_from_response(response):
    """Return (message, is_window_error) for a rejected WhatsApp send.

    Distinguishing the 24-hour customer-service window from any other failure
    lets the inbox tell an agent that WhatsApp blocked the reply rather than
    that the network hiccuped.
    """
    detail = "WhatsApp rejected the message."
    is_window = False
    try:
        payload = response.json()
    except Exception:
        payload = None
    error = payload.get("error") if isinstance(payload, dict) else None
    if isinstance(error, dict):
        message = error.get("message")
        if message:
            detail = str(message)
        for key in ("code", "error_subcode"):
            try:
                if int(error.get(key)) in WA_WINDOW_ERROR_CODES:
                    is_window = True
            except (TypeError, ValueError):
                pass
    if not is_window:
        lowered = str(detail).lower()
        if "24 hour" in lowered or "24-hour" in lowered or "re-engagement" in lowered:
            is_window = True
    if is_window:
        detail = ("WhatsApp's 24-hour window has closed for this customer — they must "
                  "message you first before you can reply.")
    return detail, is_window


def crm_send_whatsapp(wa_number, text, channel=None):
    """Send a WhatsApp text from the company channel. Returns (ok, detail)."""
    creds = wa_outbound_credentials(channel)
    if creds is None:
        return False, ("WhatsApp delivery is not configured on this deployment — open the "
                       "inbox once so the channel credentials are registered.")
    try:
        response = requests.post(
            f"https://graph.facebook.com/v18.0/{creds['phone_id']}/messages",
            headers={"Authorization": "Bearer " + str(creds['token']),
                     "Content-Type": "application/json"},
            json={"messaging_product": "whatsapp", "to": wa_number,
                  "type": "text", "text": {"body": text}},
            timeout=20,
        )
        if response.status_code >= 400:
            detail, is_window = wa_error_from_response(response)
            print(f"CRM send failed: {response.status_code} {response.text}")
            return False, detail
        return True, ""
    except Exception as e:
        print(f"CRM send error: {e}")
        return False, str(e)


def crm_send_whatsapp_payload(wa_number, payload, channel=None):
    """Send one raw WhatsApp message payload from the company channel."""
    creds = wa_outbound_credentials(channel)
    if creds is None:
        return False, ("WhatsApp delivery is not configured on this deployment — open the "
                       "inbox once so the channel credentials are registered.")
    body = dict(payload)
    body["messaging_product"] = "whatsapp"
    body["to"] = wa_number
    try:
        response = requests.post(
            f"https://graph.facebook.com/v18.0/{creds['phone_id']}/messages",
            headers={"Authorization": "Bearer " + str(creds['token']),
                     "Content-Type": "application/json"},
            json=body,
            timeout=20,
        )
        if response.status_code >= 400:
            detail, is_window = wa_error_from_response(response)
            print(f"CRM send failed: {response.status_code} {response.text}")
            return False, detail
        return True, ""
    except Exception as e:
        print(f"CRM send error: {e}")
        return False, str(e)


def company_channel_track(display_phone_number, sender_id, recipient, body,
                          message_type="text", delivered=True, staff=True):
    """Record a message that belongs to a company WhatsApp conversation.

    Only messages sent back to the person who just wrote in are recorded, so
    notifications the platform sends to third parties never pollute the inbox.
    """
    if not display_phone_number or not sender_id or not recipient or not body:
        return None
    if str(display_phone_number) not in COMPANY_SYSTEM_WA_NUMBERS:
        return None
    if str(recipient)[-15:] != str(sender_id)[-15:]:
        return None
    return crm_record_message(sender_id, "outbound", "staff" if staff else "bot", body,
                              message_type, company_reg=COMPANY_SYSTEM_PREFIX,
                              channel=display_phone_number, delivered=delivered,
                              is_staff=staff)


