# Basket prices per pack size, "product-id|size" -> amount, for example
# SHOP_PRICES='{"foam-bath|500ml": 2.50}'. An unpriced cart can still be
# ordered, it just cannot be paid for up front.
SHOP_PRICES = {}
try:
    SHOP_PRICES = json.loads(os.getenv("SHOP_PRICES", "") or "{}")
except Exception as _price_error:
    print(f"SHOP_PRICES could not be read: {_price_error}")


def paynow_configured():
    return bool(PAYNOW_INTEGRATION_ID and PAYNOW_INTEGRATION_KEY)


def _shop_price_book():
    """Selling prices saved in the CRM portal, keyed product|pack size.

    Reads the catalogue cache rather than the database so a price edit takes
    effect for the very next customer message without an extra query.
    """
    return _shop_catalog()["prices"]


def shop_price(item):
    """Price for one cart line, or None when the business has not set one.

    A price edited in the CRM portal beats the SHOP_PRICES environment
    variable, so the business can reprice without a redeploy.
    """
    key = f"{item.get('id')}|{item.get('size')}"
    value = _shop_price_book().get(key)
    if value is None:
        value = SHOP_PRICES.get(key)
    if value is None:
        return None
    try:
        return round(float(value), 2)
    except (TypeError, ValueError):
        return None


def shop_cart_total(cart):
    """Order total, or None when any line is missing a price."""
    total = 0.0
    for item in cart or []:
        price = shop_price(item)
        if price is None:
            return None
        total += price * int(item.get("qty") or 0)
    return round(total, 2)

