def ensure_shop_tables():
    """Create the shopping assistant tables the first time they are needed."""
    global _shop_tables_ready
    if _shop_tables_ready:
        return
    with get_db() as (cursor, connection):
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_sessions (
                session_key VARCHAR(80) PRIMARY KEY,
                state TEXT,
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_orders (
                id SERIAL PRIMARY KEY,
                reference VARCHAR(32) UNIQUE,
                customer_name VARCHAR(200),
                company VARCHAR(200),
                phone VARCHAR(40),
                email VARCHAR(200),
                delivery_address TEXT,
                channel VARCHAR(20),
                wa_number VARCHAR(32),
                chat_id INTEGER,
                notes TEXT,
                item_count INTEGER DEFAULT 0,
                status VARCHAR(20) DEFAULT 'new',
                created_at TIMESTAMP DEFAULT NOW()
            );
        """)
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_order_items (
                id SERIAL PRIMARY KEY,
                order_id INTEGER,
                product VARCHAR(200),
                pack_size VARCHAR(100),
                quantity INTEGER,
                created_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # The price the line was sold at. Without it a reprinted receipt would
        # show whatever the catalogue says today rather than what the customer
        # actually agreed to pay, which is the wrong answer on a money document.
        cursor.execute("ALTER TABLE shop_order_items ADD COLUMN IF NOT EXISTS unit_price NUMERIC(12, 2);")
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_payment_events (
                id SERIAL PRIMARY KEY,
                reference VARCHAR(32),
                event VARCHAR(40),
                status VARCHAR(40),
                payload TEXT,
                created_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # Catalogue overrides edited from the CRM portal. Rows are sparse: a
        # product with no row keeps the name and summary shipped in code.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_products (
                product_id VARCHAR(80) PRIMARY KEY,
                display_name VARCHAR(200),
                summary TEXT,
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # Products created from the CRM portal rather than shipped in code. They
        # need an order position so the browse list stays stable between edits.
        cursor.execute("ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS is_custom BOOLEAN DEFAULT FALSE;")
        cursor.execute("ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS position INTEGER DEFAULT 0;")
        # The product's picture, as a path under the app's static folder rather
        # than a URL: the file is uploaded here, so a deployment that moves domain
        # does not leave every product pointing at the old host.
        cursor.execute("ALTER TABLE shop_products ADD COLUMN IF NOT EXISTS image_path VARCHAR(300);")
        # Pack sizes for products added in the portal. Built-in products keep the
        # sizes declared in code and have no rows here.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_product_sizes (
                product_id VARCHAR(80),
                pack_size VARCHAR(100),
                position INTEGER DEFAULT 0,
                PRIMARY KEY (product_id, pack_size)
            );
        """)
        # Products removed from the portal. The seeder checks this so a product
        # deleted on purpose is not restored from the code defaults on the next
        # worker start.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_product_removed (
                product_id VARCHAR(80) PRIMARY KEY,
                display_name VARCHAR(200),
                removed_by VARCHAR(200),
                removed_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # Selling prices per pack size, editable from the CRM portal. These win
        # over the SHOP_PRICES environment variable.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_product_prices (
                product_id VARCHAR(80),
                pack_size VARCHAR(100),
                price NUMERIC(12, 2),
                updated_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (product_id, pack_size)
            );
        """)
        # The shops a customer can collect from, or that deliver from. They are
        # business data rather than deployment data, so they are managed in the
        # portal and the assistant reads whatever is there.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_shops (
                shop_id VARCHAR(60) PRIMARY KEY,
                name VARCHAR(200),
                address TEXT,
                phone VARCHAR(40),
                position INTEGER DEFAULT 0,
                active BOOLEAN DEFAULT TRUE,
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # The company's own branding, stored as one row rather than a settings
        # table: there is exactly one set of these and a single row makes that
        # explicit. The logo path follows the product pictures - a file under the
        # static folder, referenced by path - so the same asset serves the portal
        # and every document a customer receives.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_branding (
                brand_key VARCHAR(40) PRIMARY KEY,
                logo_path VARCHAR(300),
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # The people at a shop who are told when an order lands there. Kept per
        # shop rather than as system users: a shop's staff are not the same as the
        # portal's users, and most of them will never sign in to anything.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_staff (
                id SERIAL PRIMARY KEY,
                shop_id VARCHAR(60),
                name VARCHAR(200),
                wa_number VARCHAR(32),
                position INTEGER DEFAULT 0,
                active BOOLEAN DEFAULT TRUE,
                created_at TIMESTAMP DEFAULT NOW(),
                updated_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # The staff number is unique per shop, so the same person is not messaged
        # twice about one order because they were entered under two names.
        cursor.execute("""
            CREATE UNIQUE INDEX IF NOT EXISTS shop_staff_shop_number
            ON shop_staff (shop_id, wa_number);
        """)
        # Stock of one pack size at one shop. A row only exists once someone has
        # counted it, so a product that has never been stocked is untracked rather
        # than zero - the difference between "none left" and "nobody has said".
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_stock (
                shop_id VARCHAR(60),
                product_id VARCHAR(80),
                pack_size VARCHAR(100),
                quantity INTEGER DEFAULT 0,
                updated_at TIMESTAMP DEFAULT NOW(),
                PRIMARY KEY (shop_id, product_id, pack_size)
            );
        """)
        # Every change to a shop's stock, so a count can be explained later. A
        # deduction from an order is only trustworthy if the movement is recorded.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_stock_movements (
                id SERIAL PRIMARY KEY,
                shop_id VARCHAR(60),
                product_id VARCHAR(80),
                pack_size VARCHAR(100),
                delta INTEGER,
                quantity_after INTEGER,
                reason VARCHAR(40),
                reference VARCHAR(32),
                note TEXT,
                created_by VARCHAR(200),
                created_at TIMESTAMP DEFAULT NOW()
            );
        """)
        cursor.execute("""
            ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS delivery_method VARCHAR(24)
            DEFAULT 'delivery';
        """)
        cursor.execute("""
            ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS fulfilled_at TIMESTAMP;
        """)
        # Bring installs created before these columns existed up to date.
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS wa_number VARCHAR(32);")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS chat_id INTEGER;")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS payment_method VARCHAR(20);")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS payment_status VARCHAR(24) DEFAULT 'unpaid';")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS payment_reference VARCHAR(80);")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS payment_poll_url TEXT;")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS payment_amount NUMERIC(12, 2);")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS paid_at TIMESTAMP;")
        # Set when a customer cancels from the assistant. Kept as its own column
        # rather than only a status value so the cancellation is datable and can
        # be filtered on without reinterpreting the status vocabulary.
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS cancelled_at TIMESTAMP;")
        # The shop that will hand the goods over, and that the stock comes off. It
        # is picked by the customer, so it is part of the order rather than
        # something inferred later.
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS shop_id VARCHAR(60);")
        # Set once the order has taken its stock off a shop. It is what makes the
        # deduction happen exactly once, however many of the payment routes fire.
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS stock_deducted_at TIMESTAMP;")
        # Reminders a customer has asked for from the assistant. Kept as their own
        # rows rather than a flag on the order so the reason and the moment are
        # both on record when the sales team follows one up.
        cursor.execute("""
            CREATE TABLE IF NOT EXISTS shop_order_reminders (
                id SERIAL PRIMARY KEY,
                reference VARCHAR(32),
                wa_number VARCHAR(32),
                reason VARCHAR(60),
                created_at TIMESTAMP DEFAULT NOW()
            );
        """)
        # Where the order has got to, in the business's own words, set by staff
        # from the portal. Kept beside `status` rather than replacing it: the
        # machine vocabulary the rest of the system reasons about is untouched.
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS stage VARCHAR(24);")
        # When the stage last moved, so the customer can be told how fresh the
        # update is and staff can see which orders have gone quiet.
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS stage_at TIMESTAMP;")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS stage_by VARCHAR(200);")
        # Who placed the order. 'customer' is one the customer built in the
        # assistant; 'agent' is one a member of staff built in the portal on their
        # behalf. Kept as its own column rather than inferred from `channel`,
        # because the channel records where the conversation happened and an agent
        # order is sent over the same WhatsApp channel a customer order arrives on.
        cursor.execute("""
            ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS created_by VARCHAR(20)
            DEFAULT 'customer';
        """)
        # Set only for an agent order, until the customer accepts or declines it.
        # A draft is not a real order: it must not be picked, packed or paid for
        # while nobody has agreed to it.
        cursor.execute("""
            ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS draft BOOLEAN DEFAULT FALSE;
        """)
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS confirmed_at TIMESTAMP;")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS declined_at TIMESTAMP;")
        # The member of staff who built it, and the note they sent with it, so the
        # customer's confirmation carries the same context the agent intended.
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS created_by_name VARCHAR(200);")
        cursor.execute("ALTER TABLE shop_orders ADD COLUMN IF NOT EXISTS agent_note TEXT;")
        connection.commit()
    _shop_tables_ready = True


def shop_load_state(key):
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT state FROM shop_sessions WHERE session_key = %s", (key,))
            row = cursor.fetchone()
        if row and row[0]:
            return json.loads(row[0])
    except Exception as e:
        print(f"shop state load error: {e}")
    return {}


def shop_save_state(key, state):
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO shop_sessions (session_key, state, updated_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (session_key) DO UPDATE
                SET state = EXCLUDED.state, updated_at = NOW()
            """, (key, json.dumps(state)))
            connection.commit()
    except Exception as e:
        print(f"shop state save error: {e}")


def _shop_text(text):
    return {"type": "text", "text": text}


def _shop_options(text, options):
    return {"type": "options", "text": text, "options": [{"id": o[0], "label": o[1]} for o in options]}


# ------------------------------------------------------- message framing --
# A header and a footer on the messages a customer sees most: the welcome, the
# results of something they asked for, and the notices about their order. The
# short mid-flow prompts ("How many units?", "Which pack size?") are deliberately
# left plain, because a footer under every one of them would be noise in a
# conversation that is already several messages long.
#
# The footer is styled to match the message rather than stamped on identically:
# WhatsApp has no font families, so the only styling available is weight
# (asterisks), the separator glyph and the emoji. Each theme therefore carries
# its own accent so the thread reads as one designed system, and a theme with no
# accent falls back to the plain brand line.
BRAND_NAME_FOOTER = COMPANY_SYSTEM_NAME
BRAND_NAME_FOOTER_SUFFIX = "Client Portal"

# theme -> (header glyph, header label, footer separator glyph)
SHOP_MESSAGE_THEMES = {
    "welcome": ("👋", "Welcome", "👋"),
    "menu": ("🛍️", "Main menu", "🛍️"),
    "browse": ("🛍️", "Browse products", "🛍️"),
    "product": ("🧴", "Product", "🧴"),
    "cart": ("🛒", "Your cart", "🛒"),
    "order": ("📦", "Your order", "📦"),
    "orders": ("📦", "Your orders", "📦"),
    "track": ("📦", "Tracking", "📦"),
    "payment": ("💳", "Payment", "💳"),
    "help": ("🙋", "Help", "🙋"),
    "about": ("🏢", "About us", "🏢"),
    "search": ("🔎", "Search", "🔎"),
    "language": ("🌐", "Language", "🌐"),
    "notice": ("🔔", "Update", "🔔"),
    "problem": ("⚠️", "Something to check", "⚠️"),
    "done": ("✅", "Done", "✅"),
}


def _shop_strip_emoji(text):
    """The text with emoji and pictographs removed, spacing tidied.

    Applied to headers and footers only. The body keeps its emoji, because a
    glyph in front of a sentence is part of how that sentence reads; the header
    and footer are chrome, and chrome with a leading emoji on every message makes
    the thread look noisy rather than designed.
    """
    if not text:
        return text
    kept = []
    for character in text:
        code = ord(character)
        # The pictographic, symbol, dingbat and transport blocks, plus the
        # variation selectors and zero-width joiners that hold emoji sequences
        # together. Anything from those is dropped; ordinary punctuation such as
        # the middle dot and the apostrophe is kept.
        if (0x1F000 <= code <= 0x1FAFF or 0x2600 <= code <= 0x27BF
                or 0x2B00 <= code <= 0x2BFF or 0xFE0F == code or 0x200D == code
                or 0x2190 <= code <= 0x21FF or 0x2700 <= code <= 0x27BF
                or 0x1F1E6 <= code <= 0x1F1FF or code == 0x20E3):
            continue
        kept.append(character)
    # A leading "·" or a doubled space is left behind when a glyph beside it goes.
    cleaned = "".join(kept)
    cleaned = re.sub(r"^[\s·•\-]+", "", cleaned)
    cleaned = re.sub(r"\s{2,}", " ", cleaned)
    cleaned = re.sub(r"\s+([,.!?;:])", r"\1", cleaned)
    return cleaned.strip()


def _shop_frame(message, theme, header=True):
    """Tag a message with the header theme it should carry.

    The framing is attached here rather than wrapped around the text, so the
    translation pass still sees the original sentence: a header baked into the
    body would be sent to the translator as part of the customer's words.
    """
    if not isinstance(message, dict):
        return message
    message["theme"] = theme
    if not header:
        message["no_header"] = True
    return message


def _shop_message_header(theme, language="en"):
    """The bold header line for a theme, or '' when the theme is unknown.

    The glyph is stripped: headers are bold text only.
    """
    _glyph, label = SHOP_MESSAGE_THEMES.get(theme, ("", ""))[:2]
    if not label:
        return ""
    return f"*{_shop_strip_emoji(_shop_translate_text(label, language))}*"


def _shop_message_footer(theme=""):
    """The footer line for a theme.

    Plain bold brand text, with no accent glyph. The themed glyph used to sit in
    front of the brand, which put an emoji on every single message.
    """
    return f"*{BRAND_NAME_FOOTER} · {BRAND_NAME_FOOTER_SUFFIX}*"


def _shop_apply_framing(text, message, language="en"):
    """Wrap one message's text in its header and footer, if it carries a theme."""
    theme = (message or {}).get("theme")
    if not theme or not text:
        return text
    header = "" if (message or {}).get("no_header") else _shop_message_header(theme, language)
    # The footer is dropped if the message is already at the button body limit,
    # because a header and footer that push a prompt past 1024 would make the
    # interactive message unsendable and cost the customer their buttons.
    footer = _shop_message_footer(theme)
    candidate = f"{header}\n\n{text}" if header else text
    if len(candidate) + len(footer) + 2 <= WA_BUTTON_BODY_LIMIT:
        return f"{candidate}\n\n{footer}"
    return candidate




