@app.route('/portal/crm')
def portal_crm():
    user, denied = company_system_guard('crm')
    if denied:
        return denied
    try:
        # Warm the outbound credentials so the first reply is not sent from a
        # worker that has yet to see a webhook.
        wa_load_channels()
    except Exception as e:
        print(f"channel warmup skipped: {e}")
    try:
        chats = _crm_chats('all')
    except Exception as e:
        print(f"CRM data error: {e}")
        chats = []
    try:
        orders = orders_overview('today', 'all')
    except Exception as e:
        print(f"CRM order error: {e}")
        orders = []
    try:
        catalog = crm_catalog()
    except Exception as e:
        print(f"CRM catalogue error: {e}")
        catalog = []
    try:
        removed = crm_removed_products()
    except Exception as e:
        print(f"CRM removed products error: {e}")
        removed = []
    return render_template('crm_portal.html', user=user, active_nav='crm',
                           nav_modules=user_modules(user),
                           chats=chats, orders=orders,
                           catalog=catalog,
                           removed=removed,
                           limits=catalog_limits(),
                           # The logo is rendered on the page rather than fetched
                           # by the browser, so a missing file shows as no logo
                           # instead of a broken image.
                           logo_url=company_logo_url(),
                           logo_max_mb=LOGO_MAX_BYTES // (1024 * 1024),
                           # Rendered so the shop name field cannot drift from the
                           # limit the endpoint actually enforces.
                           shop_name_limit=SHOP_NAME_LIMIT,
                           channel_number=company_system_channel_label(),
                           **company_system_stats())


@app.route('/api/access/matrix')
def access_matrix_api():
    user = company_system_user()
    if not user:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    if not user['modules'].get('access'):
        return jsonify({'success': False, 'message': 'You cannot manage user access.'}), 403
    try:
        employees = access_matrix()
    except Exception as e:
        print(f"access matrix error: {e}")
        return jsonify({'success': False, 'message': 'Unable to load the access matrix.'}), 500
    return jsonify({
        'success': True,
        'employees': employees,
        'modules': [{'key': module['key'],
                     'title': module['matrix_title'],
                     'full_title': module['title']} for module in COMPANY_MODULES],
        'access_managers': sum(1 for employee in employees if employee['modules'].get('access')),
    })


@app.route('/api/access/toggle', methods=['POST'])
def access_toggle_api():
    user = company_system_user()
    if not user:
        return jsonify({'success': False, 'message': 'Unauthorized'}), 401
    if not user['modules'].get('access'):
        return jsonify({'success': False, 'message': 'You cannot manage user access.'}), 403

    payload = request.get_json(silent=True) or {}
    employee_id = payload.get('employee_id')
    module = (payload.get('module') or '').strip()
    enabled = bool(payload.get('enabled'))

    if employee_id is None or module not in COMPANY_MODULE_KEYS:
        return jsonify({'success': False, 'message': 'Unknown employee or portal.'}), 400

    # Nobody may switch off their own access management: it is the only thing
    # stopping the company from locking itself out of this page.
    if int(employee_id) == int(user['id']) and module == 'access' and not enabled:
        return jsonify({'success': False,
                        'message': 'You cannot remove your own access management permission. '
                                   'Ask another access manager to do it, or grant someone else first.'}), 400

    if not set_module_access(employee_id, module, enabled, user['id']):
        return jsonify({'success': False, 'message': 'Could not update access. Please try again.'}), 500

    target_name = next((employee.get('name') for employee in access_matrix()
                        if str(employee.get('id')) == str(employee_id)), str(employee_id))
    module_title = next((item['title'] for item in COMPANY_MODULES if item['key'] == module), module)
    log_activity("granted_access" if enabled else "revoked_access", "access",
                 f"{'Granted' if enabled else 'Revoked'} {module_title} access for {target_name}",
                 target=target_name,
                 details={"employee_id": employee_id, "module": module, "enabled": enabled},
                 user=user)

    return jsonify({'success': True})


@app.route('/api/crm/summary')
def crm_summary():
    user, error = portal_api_user('crm')
    if error:
        return error
    return jsonify({'success': True,
                    'chats': _crm_chats(request.args.get('filter', 'all'),
                                        request.args.get('search')),
                    'stats': company_system_stats()})


# ------------------------------------------------------------------- web push --
@app.route('/api/push/config')
def push_config():
    """Tell the browser whether notifications can be enabled on this deployment."""
    user, error = portal_api_user('crm')
    if error:
        return error
    return jsonify({'success': True,
                    'enabled': push_configured(),
                    'public_key': VAPID_PUBLIC_KEY,
                    'subscribed': len(_push_list_subscriptions()) if push_configured() else 0})


@app.route('/api/push/subscribe', methods=['POST'])
def push_subscribe():
    user, error = portal_api_user('crm')
    if error:
        return error
    if not push_configured():
        return jsonify({'success': False,
                        'message': 'Notifications are not configured on this deployment yet.'}), 503
    payload = request.get_json(silent=True) or {}
    subscription = dict(payload.get('subscription') or {})
    subscription['user_agent'] = (request.headers.get('User-Agent') or '')[:300]
    if not push_save_subscription(subscription, user):
        return jsonify({'success': False,
                        'message': 'That subscription could not be saved.'}), 400
    log_activity("enabled_notifications", "chat",
                 "Turned on WhatsApp notifications for this device",
                 target="notifications", user=user)
    return jsonify({'success': True})


@app.route('/api/push/unsubscribe', methods=['POST'])
def push_unsubscribe():
    user, error = portal_api_user('crm')
    if error:
        return error
    payload = request.get_json(silent=True) or {}
    push_remove_subscription(payload.get('endpoint'))
    log_activity("disabled_notifications", "chat",
                 "Turned off WhatsApp notifications for this device",
                 target="notifications", user=user)
    return jsonify({'success': True})


# --------------------------------------------------------------- order analytics
ORDER_PERIODS = {
    # key: (label, interval used to bound created_at)
    "today": ("Today", "1 day"),
    "yesterday": ("Yesterday", "2 days"),
    "this_week": ("This week", "7 days"),
    "last_week": ("Last week", "14 days"),
    "this_month": ("This month", "31 days"),
    "last_month": ("Last month", "62 days"),
    "all": ("All time", None),
}
# Timestamps are stored in UTC but the business day is Zimbabwe time, so the
# period boundaries are shifted before the date is taken. Without the shift an
# order taken at 22:00 local (20:00 UTC) would still count as the same day, but
# one taken at 01:00 local belongs to the previous UTC day and would be reported
# under the wrong date.
ORDER_TZ_SHIFT = DISPLAY_TZ_OFFSET


def order_period_where(alias="shop_orders"):
    """Period filters for the orders views, as SQL over one table alias.

    `created_at` must be qualified: the overview query joins whatsapp_chats,
    which also has a created_at, so a bare reference makes the whole query fail
    with "column reference created_at is ambiguous" and the view renders empty.
    The alias is a parameter because one caller joins the chats table and the
    other does not, so a single hard-coded prefix cannot serve both.
    """
    created = f"({alias}.created_at + INTERVAL '{ORDER_TZ_SHIFT} hours')"
    today = f"(CURRENT_TIMESTAMP + INTERVAL '{ORDER_TZ_SHIFT} hours')::date"
    return {
        "today": f"{created}::date = {today}",
        "yesterday": f"{created}::date = {today} - INTERVAL '1 day'",
        "this_week": (f"{created} >= date_trunc('week', "
                      f"CURRENT_TIMESTAMP + INTERVAL '{ORDER_TZ_SHIFT} hours')"),
        "last_week": (f"{created} >= date_trunc('week', "
                      f"CURRENT_TIMESTAMP + INTERVAL '{ORDER_TZ_SHIFT} hours') - INTERVAL '7 days' "
                      f"AND {created} < date_trunc('week', "
                      f"CURRENT_TIMESTAMP + INTERVAL '{ORDER_TZ_SHIFT} hours')"),
        "this_month": (f"{created} >= date_trunc('month', "
                       f"CURRENT_TIMESTAMP + INTERVAL '{ORDER_TZ_SHIFT} hours')"),
        "last_month": (f"{created} >= date_trunc('month', "
                       f"CURRENT_TIMESTAMP + INTERVAL '{ORDER_TZ_SHIFT} hours') - INTERVAL '1 month' "
                       f"AND {created} < date_trunc('month', "
                       f"CURRENT_TIMESTAMP + INTERVAL '{ORDER_TZ_SHIFT} hours')"),
    }



def orders_overview(period="today", payment="all", fulfilment="all", limit=50):
    """Order rows for the CRM dashboard, filtered by period and status."""
    ensure_shop_tables()
    # This query aliases shop_orders as `orders` and joins the chats table, so
    # every filtered column is qualified with that alias.
    clause = order_filter_clause(period, payment, fulfilment, "orders")
    query = f"""
        SELECT orders.reference, orders.customer_name, orders.company, orders.phone,
               orders.delivery_address, orders.item_count, orders.payment_method,
               COALESCE(orders.payment_status, 'unpaid'), orders.payment_amount,
               COALESCE(orders.delivery_method, 'delivery'), orders.status, orders.created_at,
               orders.wa_number, COALESCE(chats.wa_profile_name, chats.display_name),
               orders.fulfilled_at, orders.cancelled_at,
               COALESCE(orders.stage, ''), orders.stage_at, orders.stage_by,
               COALESCE(orders.created_by, 'customer'), orders.draft,
               orders.created_by_name, orders.declined_at
        FROM shop_orders orders
        LEFT JOIN whatsapp_chats chats ON chats.wa_number = orders.wa_number
        WHERE {clause}
        ORDER BY orders.created_at DESC
        LIMIT {int(limit)}
    """
    try:
        with get_db() as (cursor, connection):
            cursor.execute(query)
            rows = cursor.fetchall()
    except Exception as e:
        print(f"order overview error: {e}")
        return []
    orders = []
    for row in rows:
        orders.append({
            "reference": row[0],
            "customer_name": row[1] or row[13] or "",
            "company": row[2] or "",
            "phone": row[3] or "",
            "address": row[4] or "",
            "items": row[5] or 0,
            "method": row[6] or "later",
            "payment_status": row[7] or "unpaid",
            # One line for what the money is doing, so the rows, the recent list
            # and the chatbot all read the same.
            "payment_label": _shop_order_payment_badge(
                (row[7] or "").lower() == "paid", row[6], row[9], row[7]),
            "amount": float(row[8]) if row[8] is not None else None,
            "delivery_method": row[9] or "delivery",
            "status": row[10] or "new",
            "created_at": fmt_time(row[11], "%d %b %Y %H:%M"),
            "wa_number": row[12] or "",
            "profile_name": row[13] or "",
            "fulfilled_at": fmt_time(row[14], "%d %b %Y %H:%M"),
            "cancelled_at": fmt_time(row[15], "%d %b %Y %H:%M"),
            "cancelled": row[15] is not None or (row[10] or "") == "cancelled",
            "stage": row[16] or "",
            "stage_label": SHOP_STAGE_LABELS.get((row[16] or "").strip().lower(), ""),
            "stage_at": fmt_time(row[17], "%d %b %Y %H:%M"),
            "stage_by": row[18] or "",
            # Who placed the order. A draft is one an agent built that the customer
            # has not answered yet, so the row says so rather than letting it read
            # as work already agreed.
            "origin": row[19] or "customer",
            "agent_created": (row[19] or "customer") == "agent",
            "draft": bool(row[20]),
            "created_by_name": row[21] or "",
            "declined_at": fmt_time(row[22], "%d %b %Y %H:%M"),
        })
    return orders


def order_detail(reference):
    """One order with its lines, for the sales view and the printed documents.

    Line prices are read from shop_order_items.unit_price, which is written at
    the moment of sale, so a document reprinted next month still shows what the
    customer agreed to pay. `total` prefers the amount actually charged, because
    that is what the payment was settled against; `subtotal` is the sum of the
    lines and the two can differ when a discount was agreed by hand.
    """
    ensure_shop_tables()
    reference = (reference or "").strip()
    if not reference:
        return None
    try:
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT orders.id, orders.reference, orders.customer_name, orders.company,
                       orders.phone, orders.email, orders.delivery_address, orders.channel,
                       orders.wa_number, orders.notes, orders.item_count,
                       COALESCE(orders.status, 'new'),
                       COALESCE(orders.payment_method, ''),
                       COALESCE(orders.payment_status, 'unpaid'),
                       orders.payment_amount, orders.paid_at,
                       COALESCE(orders.delivery_method, 'delivery'),
                       orders.fulfilled_at, orders.created_at,
                       COALESCE(chats.wa_profile_name, chats.display_name),
                       orders.shop_id, orders.stock_deducted_at,
                       COALESCE(orders.stage, ''), orders.stage_at, orders.stage_by,
                       COALESCE(orders.created_by, 'customer'), orders.draft,
                       orders.created_by_name, orders.agent_note,
                       orders.confirmed_at, orders.declined_at
                FROM shop_orders orders
                LEFT JOIN whatsapp_chats chats ON chats.wa_number = orders.wa_number
                WHERE orders.reference = %s
            """, (reference,))
            row = cursor.fetchone()
            if not row:
                return None
            order_id = row[0]
            cursor.execute("""
                SELECT product, pack_size, quantity, unit_price
                FROM shop_order_items WHERE order_id = %s ORDER BY id
            """, (order_id,))
            item_rows = cursor.fetchall()
    except Exception as e:
        print(f"order detail error: {e}")
        return None

    lines = []
    subtotal = 0.0
    priced = bool(item_rows)
    for item_row in item_rows:
        quantity = int(item_row[2] or 0)
        unit_price = float(item_row[3]) if item_row[3] is not None else None
        if unit_price is None:
            priced = False
            line_total = None
        else:
            line_total = round(unit_price * quantity, 2)
            subtotal += line_total
        lines.append({
            "product": item_row[0] or "",
            "pack_size": item_row[1] or "",
            "quantity": quantity,
            # The catalogue price is only offered as a fallback for orders taken
            # before prices were recorded, and is labelled as such.
            "unit_price": unit_price,
            "line_total": line_total,
        })
    subtotal = round(subtotal, 2)
    charged = float(row[14]) if row[14] is not None else None
    # Only looked up when the order actually names a shop, so an order taken
    # before shops existed costs no extra query.
    fulfilling_shop = shop_by_id(row[20]) if row[20] else None
    return {
        "reference": row[1],
        "customer_name": row[2] or row[19] or "",
        "company": row[3] or "",
        "phone": row[4] or "",
        "email": row[5] or "",
        "address": row[6] or "",
        "channel": row[7] or "",
        "wa_number": row[8] or "",
        "notes": row[9] or "",
        "item_count": row[10] or 0,
        "status": row[11],
        "payment_method": row[12],
        "payment_status": row[13],
        # One line the shop's staff can act on: whether the money is settled or
        # has to be taken at hand-over.
        "payment_status_label": (
            f"Paid {SHOP_PAYMENT_METHOD_LABELS.get(_shop_payment_method(row[12]), '')}".strip()
            if (row[13] or "").lower() == "paid"
            else ("Unpaid — collect "
                  + ("on delivery" if row[16] == "delivery" else "at the shop")
                  if (row[13] or "unpaid").lower() != "paid" else "Unpaid")),
        "amount_charged": charged,
        "paid_at": fmt_time(row[15], "%d %b %Y %H:%M"),
        "delivery_method": row[16],
        "fulfilled_at": fmt_time(row[17], "%d %b %Y %H:%M"),
        "created_at": fmt_time(row[18], "%d %b %Y %H:%M"),
        "profile_name": row[19] or "",
        "shop_key": row[20],
        "shop": (fulfilling_shop or {}).get("name", ""),
        "shop_address": (fulfilling_shop or {}).get("address", ""),
        "stock_deducted_at": fmt_time(row[21], "%d %b %Y %H:%M"),
        "stage": row[22] or "",
        "stage_at": fmt_time(row[23], "%d %b %Y %H:%M"),
        "stage_by": row[24] or "",
        "origin": row[25] or "customer",
        "agent_created": (row[25] or "customer") == "agent",
        "draft": bool(row[26]),
        "created_by_name": row[27] or "",
        "agent_note": row[28] or "",
        "confirmed_at": fmt_time(row[29], "%d %b %Y %H:%M"),
        "declined_at": fmt_time(row[30], "%d %b %Y %H:%M"),
        # Named `lines` rather than `items` because a dict's `.items` attribute
        # shadows a key of that name in a template, which silently breaks the
        # `{% for %}` over it.
        "lines": lines,
        "subtotal": subtotal,
        "total": charged if charged is not None else subtotal,
        "priced": priced and bool(lines),
        "currency": PAYNOW_CURRENCY,
    }


def order_payment_filter(key, alias="shop_orders"):
    """Payment filter for the orders views, qualified to one table alias."""
    filters = {
        "all": "1 = 1",
        "paid": f"{alias}.payment_status = 'paid'",
        "unpaid": f"COALESCE({alias}.payment_status, 'unpaid') <> 'paid'",
    }
    return filters.get(key) or filters["all"]


def order_fulfilment_filter(key, alias="shop_orders"):
    """Fulfilment filter for the orders views, qualified to one table alias.

    `status` must be qualified for the same reason `created_at` must be: the
    overview query joins whatsapp_chats, which has its own status column, so a
    bare reference makes the filter unusable.

    A cancelled order is excluded from every view but its own, so it can never be
    counted as a sale or mistaken for work still to be done.
    """
    active = (f"{alias}.cancelled_at IS NULL AND "
              f"COALESCE({alias}.status, 'new') <> 'cancelled'")
    cancelled = (f"({alias}.cancelled_at IS NOT NULL OR "
                 f"COALESCE({alias}.status, 'new') = 'cancelled')")
    filters = {
        "all": active,
        "delivery": f"COALESCE({alias}.delivery_method, 'delivery') = 'delivery' AND {active}",
        "collection": f"{alias}.delivery_method = 'collection' AND {active}",
        "pending": (f"{alias}.fulfilled_at IS NULL AND {alias}.status <> 'closed' "
                    f"AND {active}"),
        "fulfilled": f"{alias}.fulfilled_at IS NOT NULL OR {alias}.status = 'closed'",
        "cancelled": cancelled,
    }
    return filters.get(key) or filters["all"]


def order_filter_clause(period="today", payment="all", fulfilment="all", alias="shop_orders"):
    """The full WHERE for a shop_orders read, as SQL over one table alias.

    Every caller passes the alias its own FROM clause uses, so the same filters
    work whether the query joins the chats table or not.
    """
    where = ["1 = 1"]
    periods = order_period_where(alias)
    if period in periods:
        where.append(periods[period])
    where.append(order_payment_filter(payment, alias))
    where.append(order_fulfilment_filter(fulfilment, alias))
    return " AND ".join(where)


# -------------------------------------------------------- order card buckets --
# The cards above the orders table. Each bucket answers one question the sales
# team actually asks, and every one of them is derived from `stage`, `status`
# and `fulfilled_at` - the same three columns the assistant reads when it tells a
# customer where their order has got to. Nothing here invents a state the
# chatbot could not have produced, so a card can never disagree with what the
# customer was told.
#
# `stage` is the business's own words for where the order is (see
# SHOP_ORDER_STAGES); `fulfilled_at`/`cancelled_at` are the closed states. An
# order that has never been moved has no stage and is still awaiting work.
ORDER_CARD_BUCKETS = (
    ("awaiting", "Awaiting fulfilment",
     "No stage set yet - the order is still to be picked or packed."),
    ("preparing", "Being processed",
     "The sales team has started on it."),
    ("ready", "Ready to collect",
     "Waiting at the shop for the customer to collect."),
    ("awaiting_delivery", "Out for delivery",
     "En route to the customer's address."),
    ("delivered", "Delivered",
     "Handed over at the customer's address."),
    ("collected", "Collected",
     "Picked up from the shop by the customer."),
    ("cancelled", "Cancelled",
     "Called off before it was fulfilled."),
)


def order_bucket_clause(bucket, alias="shop_orders"):
    """The WHERE for one order card bucket, as SQL over one table alias.

    Cancelled and fulfilled orders are excluded from the open buckets rather than
    being counted twice, so the cards always add up to the orders in view.
    `stage` is only trusted when it is one of the stages this build knows about:
    a row left behind by an older version falls back to awaiting work instead of
    disappearing from every card.
    """
    cancelled = (f"({alias}.cancelled_at IS NOT NULL OR "
                 f"COALESCE({alias}.status, 'new') = 'cancelled')")
    closed = f"{alias}.fulfilled_at IS NOT NULL OR {alias}.status = 'closed'"
    open_order = f"NOT {cancelled} AND NOT ({closed})"
    stage = f"LOWER(COALESCE({alias}.stage, ''))"
    known = ", ".join(f"'{value}'" for value in SHOP_ORDER_STAGES)
    buckets = {
        "cancelled": cancelled,
        # The finished buckets also exclude cancelled rows, so an order that was
        # delivered and then cancelled is counted once, as a cancellation, and
        # the cards never sum to more than the list beneath them.
        "delivered": f"{stage} = 'delivered' AND NOT {cancelled}",
        "collected": f"{stage} = 'collected' AND NOT {cancelled}",
        "awaiting_delivery": f"{stage} = 'enroute' AND {open_order}",
        "ready": f"{stage} = 'ready' AND {open_order}",
        "preparing": f"{stage} = 'preparing' AND {open_order}",
        # Anything open that has not been moved, including a stage this build
        # does not recognise, so no open order can hide from every card.
        "awaiting": (f"{open_order} AND ({stage} NOT IN ({known}) OR "
                     f"{stage} = '')"),
    }
    return buckets.get(bucket) or buckets["awaiting"]


def order_status_counts(period="today", payment="all", fulfilment="all"):
    """How many orders sit in each card bucket for the current filters.

    One query rather than one per card, so the numbers cannot be read from
    different moments in time and add up to something other than the list below
    them.
    """
    ensure_shop_tables()
    clause = order_filter_clause(period, payment, fulfilment, "shop_orders")
    selects = []
    for bucket, _label, _hint in ORDER_CARD_BUCKETS:
        alias = f"b_{bucket}"
        selects.append(
            f"COUNT(*) FILTER (WHERE {order_bucket_clause(bucket, 'shop_orders')}) AS {alias}")
    try:
        with get_db() as (cursor, connection):
            cursor.execute(
                f"SELECT {', '.join(selects)} FROM shop_orders WHERE {clause}")
            row = cursor.fetchone()
    except Exception as e:
        print(f"order status counts error: {e}")
        row = None
    counts = {}
    for index, (bucket, _label, _hint) in enumerate(ORDER_CARD_BUCKETS):
        counts[bucket] = int(row[index] or 0) if row else 0
    return counts


def orders_analytics(period="today", payment="all", fulfilment="all"):
    """Headline sales numbers for the selected period and status filters."""
    ensure_shop_tables()
    # These counts read shop_orders without an alias.
    clause = order_filter_clause(period, payment, fulfilment, "shop_orders")
    totals = {
        "orders": _safe_scalar(f"SELECT COUNT(*) FROM shop_orders WHERE {clause}"),
        "units": _safe_scalar(
            f"SELECT COALESCE(SUM(item_count), 0) FROM shop_orders WHERE {clause}"),
        "value": _safe_scalar(
            f"SELECT COALESCE(SUM(COALESCE(payment_amount, 0)), 0) FROM shop_orders WHERE {clause}"),
        "paid": _safe_scalar(
            f"SELECT COUNT(*) FROM shop_orders WHERE {clause} AND payment_status = 'paid'"),
        "paid_value": _safe_scalar(
            f"SELECT COALESCE(SUM(COALESCE(payment_amount, 0)), 0) FROM shop_orders "
            f"WHERE {clause} AND payment_status = 'paid'"),
        "delivery": _safe_scalar(
            f"SELECT COUNT(*) FROM shop_orders WHERE {clause} "
            f"AND COALESCE(delivery_method, 'delivery') = 'delivery'"),
        "collection": _safe_scalar(
            f"SELECT COUNT(*) FROM shop_orders WHERE {clause} AND delivery_method = 'collection'"),
    }
    top_items = []
    try:
        # The top-products query joins the items table, so shop_orders is
        # aliased as `orders` and the filters are rebuilt for that alias rather
        # than textually rewritten, which produced invalid SQL.
        items_clause = order_filter_clause(period, payment, fulfilment, "orders")
        with get_db() as (cursor, connection):
            cursor.execute(f"""
                SELECT items.product, COALESCE(SUM(items.quantity), 0) AS units
                FROM shop_order_items items
                JOIN shop_orders orders ON orders.id = items.order_id
                WHERE {items_clause}
                GROUP BY items.product
                ORDER BY units DESC
                LIMIT 6
            """)
            top_items = [{"product": row[0], "units": int(row[1] or 0)}
                         for row in cursor.fetchall()]
    except Exception as e:
        print(f"top items error: {e}")
    totals["top_items"] = top_items
    totals["currency"] = PAYNOW_CURRENCY
    totals["series"] = orders_sales_series(period, payment, fulfilment)
    return totals


# How many points the sales chart shows for each period. A named period has an
# obvious grain: a single day needs hours, a week or a month needs days. All time
# is bucketed by month, because a day-by-day chart of a year is unreadable.
ORDER_SERIES_GRAIN = {
    "today": ("hour", 24, "'HH24:00'"),
    "yesterday": ("hour", 24, "'HH24:00'"),
    "this_week": ("day", 7, "'Dy'"),
    "last_week": ("day", 7, "'Dy'"),
    "this_month": ("day", 31, "'DD Mon'"),
    "last_month": ("day", 31, "'DD Mon'"),
    "all": ("month", 12, "'Mon YY'"),
}


def orders_sales_series(period="today", payment="all", fulfilment="all"):
    """Orders and value per time bucket, for the sales chart.

    generate_series fills the gaps, so a quiet hour shows as a zero rather than
    being skipped and making two busy hours look adjacent. The buckets are cut in
    business-day time, matching the period filters, so the chart and the totals
    above it agree on which day an order belongs to.
    """
    grain, slots, label_format = ORDER_SERIES_GRAIN.get(
        period, ORDER_SERIES_GRAIN["today"])
    shift = ORDER_TZ_SHIFT
    local_now = f"(CURRENT_TIMESTAMP + INTERVAL '{shift} hours')"
    if grain == "hour":
        start = f"date_trunc('day', {local_now})"
        step = "1 hour"
    elif grain == "day":
        if period == "this_week":
            start = f"date_trunc('week', {local_now})"
        elif period == "last_week":
            start = f"date_trunc('week', {local_now}) - INTERVAL '7 days'"
        elif period == "last_month":
            start = f"date_trunc('month', {local_now}) - INTERVAL '1 month'"
        else:
            start = f"date_trunc('month', {local_now})"
        step = "1 day"
    else:
        start = f"date_trunc('month', {local_now}) - INTERVAL '11 months'"
        step = "1 month"
    clause = order_filter_clause(period, payment, fulfilment, "shop_orders")
    created = f"(shop_orders.created_at + INTERVAL '{shift} hours')"
    try:
        with get_db() as (cursor, connection):
            cursor.execute(f"""
                SELECT to_char(bucket, {label_format}) AS label,
                       COUNT(shop_orders.id) AS orders,
                       COALESCE(SUM(COALESCE(shop_orders.payment_amount, 0)), 0) AS value
                FROM generate_series(
                        date_trunc('{grain}', {start}),
                        date_trunc('{grain}', {local_now}),
                        INTERVAL '{step}') AS bucket
                LEFT JOIN shop_orders
                       ON date_trunc('{grain}', {created}) = bucket
                      AND {clause}
                GROUP BY bucket
                ORDER BY bucket
                LIMIT {int(slots) + 1}
            """)
            rows = cursor.fetchall()
    except Exception as e:
        print(f"order series error: {e}")
        return []
    # generate_series is inclusive of both ends, so a day grain can return one
    # slot more than the period holds; the tail is dropped rather than relabelled.
    rows = rows[:int(slots)]
    return [{"label": row[0], "orders": int(row[1] or 0),
             "value": float(row[2] or 0)} for row in rows]


ACTIVITY_PERIODS = {
    "today": ("Today", "created_at::date = CURRENT_DATE"),
    "yesterday": ("Yesterday", "created_at::date = CURRENT_DATE - INTERVAL '1 day'"),
    "this_week": ("This week", "created_at >= date_trunc('week', CURRENT_DATE)"),
    "last_week": ("Last week",
                  "created_at >= date_trunc('week', CURRENT_DATE) - INTERVAL '7 days' "
                  "AND created_at < date_trunc('week', CURRENT_DATE)"),
    "this_month": ("This month", "created_at >= date_trunc('month', CURRENT_DATE)"),
    "last_month": ("Last month",
                   "created_at >= date_trunc('month', CURRENT_DATE) - INTERVAL '1 month' "
                   "AND created_at < date_trunc('month', CURRENT_DATE)"),
    "all": ("All time", None),
}


def activity_log_entries(period="today", category="all", employee=None,
                         date_from=None, date_to=None, limit=500):
    """Staff activity rows for the CRM activity log and its PDF export.

    A custom range wins over the named period, so the date pickers and the
    quick period buttons can share one code path.
    """
    ensure_audit_tables()
    where = ["1 = 1"]
    params = []
    if date_from or date_to:
        if date_from:
            where.append("created_at >= %s::date")
            params.append(date_from)
        if date_to:
            # Inclusive of the whole end day.
            where.append("created_at < (%s::date + INTERVAL '1 day')")
            params.append(date_to)
    elif period in ACTIVITY_PERIODS and ACTIVITY_PERIODS[period][1]:
        where.append(ACTIVITY_PERIODS[period][1])
    if category and category != "all":
        if category not in AUDIT_CATEGORIES:
            return []
        where.append("category = %s")
        params.append(category)
    if employee:
        where.append("(employee_name ILIKE %s OR employee_email ILIKE %s)")
        params.extend([f"%{employee}%", f"%{employee}%"])
    try:
        with get_db() as (cursor, connection):
            cursor.execute(f"""
                SELECT id, employee_name, employee_role, employee_email, action, category,
                       summary, target, details, ip_address, created_at
                FROM company_activity_log
                WHERE {' AND '.join(where)}
                ORDER BY created_at DESC, id DESC
                LIMIT {int(limit)}
            """, tuple(params))
            rows = cursor.fetchall()
    except Exception as e:
        print(f"activity log read error: {e}")
        return []
    entries = []
    for row in rows:
        entries.append({
            "id": row[0],
            "employee_name": row[1] or "Unknown",
            "employee_role": row[2] or "",
            "employee_email": row[3] or "",
            "action": row[4],
            "category": row[5],
            "category_label": AUDIT_CATEGORIES.get(row[5], row[5]),
            "summary": row[6] or "",
            "target": row[7] or "",
            "details": row[8] or "",
            "ip_address": row[9] or "",
            "created_at": fmt_time(row[10], "%d %b %Y %H:%M"),
            "created_iso": local_time(row[10]).isoformat() if row[10] else "",
        })
    return entries


def activity_period_label(period, date_from=None, date_to=None):
    """A readable description of the window being exported."""
    if date_from or date_to:
        if date_from and date_to:
            return f"{date_from} to {date_to}"
        if date_from:
            return f"From {date_from}"
        return f"Up to {date_to}"
    return ACTIVITY_PERIODS.get(period, ("All time", None))[0]


def crm_catalog():
    """Every product with its editable name, summary and pack prices.

    Covers the built-in range and anything added from the CRM portal, because
    WhatsApp shows them as one list and the limit applies to the total. A portal
    product is included even before it has pack sizes, so it can be finished
    here rather than becoming unreachable.
    """
    ensure_shop_tables()
    catalog = _shop_catalog()
    names = catalog.get("names") or {}
    summaries = catalog.get("summaries") or {}
    images = catalog.get("images") or {}
    rows = []

    for entry in shop_all_products():
        sizes = [{
            "size": size,
            "price": catalog["prices"].get(f"{entry['id']}|{size}"),
        } for size in entry["sizes"]]
        rows.append({
            "index": len(rows),
            "id": entry["id"],
            "name": names.get(entry["id"]) or entry["name"],
            "base_name": entry["base_name"],
            "summary": summaries.get(entry["id"]) or entry["summary"],
            "base_summary": entry["summary"],
            "sizes": sizes,
            "priced": bool(sizes) and all(item["price"] is not None for item in sizes),
            "custom": entry["custom"],
            "incomplete": False,
            "image_path": images.get(entry["id"]) or "",
            "image_url": product_image_public_url(images.get(entry["id"])),
        })

    # Products added here that cannot be sold yet: no name, or no pack sizes.
    listed = {row["id"] for row in rows}
    for product in (catalog.get("custom") or []):
        if product["id"] in listed:
            continue
        sizes = [{
            "size": size,
            "price": catalog["prices"].get(f"{product['id']}|{size}"),
        } for size in product.get("sizes") or []]
        rows.append({
            "index": len(rows),
            "id": product["id"],
            "name": names.get(product["id"]) or product.get("name") or "",
            "base_name": product.get("name") or "",
            "summary": summaries.get(product["id"]) or product.get("summary") or "",
            "base_summary": product.get("summary") or "",
            "sizes": sizes,
            "priced": False,
            "custom": True,
            "incomplete": True,
            "image_path": images.get(product["id"]) or "",
            "image_url": product_image_public_url(images.get(product["id"])),
        })
    return rows


def catalog_limits():
    """The WhatsApp limits the catalogue editor has to respect.

    `summary_limit` is the *effective* allowance, not the raw WhatsApp body cap:
    the description is rendered inside a product prompt that also carries the
    product name and the list of pack sizes, so the editor reserves room for
    those and for the pack list to grow.
    """
    return {
        "max_products": CATALOG_MAX_PRODUCTS,
        "name_limit": CATALOG_NAME_LIMIT,
        "summary_limit": CATALOG_SUMMARY_LIMIT,
        "pack_limit": CATALOG_MAX_PACKS_PER_PRODUCT,
        "product_count": len(shop_all_products()),
        # Shown in the editor so the figure is explainable rather than magic.
        "body_limit": WA_BODY_LIMIT,
        # The picture editor refuses anything else up front, so the portal can
        # name the same limits rather than only reporting the refusal.
        "image_extensions": sorted(PRODUCT_IMAGE_EXTENSIONS),
        "image_max_bytes": PRODUCT_IMAGE_MAX_BYTES,
        "image_max_mb": PRODUCT_IMAGE_MAX_BYTES // (1024 * 1024),
    }

def _clean_text(value, limit, field):
    """Normalise one catalogue field, returning (text, error)."""
    text = " ".join(str(value or "").split()).strip()
    if len(text) > limit:
        return text, (f"{field} must be {limit} characters or fewer "
                      f"(currently {len(text)}).")
    return text, None


def _clean_pack_sizes(raw_sizes):
    """Validate and de-duplicate a product's pack sizes. Returns (sizes, error)."""
    sizes, seen, errors = [], set(), []
    for value in raw_sizes or []:
        size, error = _clean_text(value, CATALOG_NAME_LIMIT, "Pack size")
        if error:
            errors.append(error)
            continue
        if not size:
            continue
        key = size.lower()
        if key in seen:
            continue
        seen.add(key)
        sizes.append(size)
    if errors:
        return [], errors[0]
    if not sizes:
        return [], "Give the product at least one pack size."
    if len(sizes) > CATALOG_MAX_PACKS_PER_PRODUCT:
        return [], (f"A product can have at most {CATALOG_MAX_PACKS_PER_PRODUCT} "
                    f"unit sizes so its list fits WhatsApp.")
    return sizes, None


def _summary_fits(name, summary, sizes):
    """True when a product prompt built from these parts fits WhatsApp.

    The prompt is *name*, the description, then "Available pack sizes: ...", all
    inside one message, so the three have to fit together rather than each on
    its own.
    """
    body = (f"🧴 *{name}*\n\n{summary}\n\n"
            f"Available pack sizes: {', '.join(sizes)}")
    return len(body) <= WA_BODY_LIMIT


def _slugify_product_id(name):
    """A stable identifier derived from the product name."""
    slug = re.sub(r"[^a-z0-9]+", "-", str(name or "").lower()).strip("-")
    return slug[:60]


def crm_product_names_taken(exclude_id=None):
    """Product names already in use, lower-cased, for duplicate detection."""
    taken = set()
    for product in shop_all_products():
        if exclude_id and product["id"] == exclude_id:
            continue
        taken.add(product["name"].strip().lower())
    return taken


def crm_add_product(display_name, summary=None, sizes=None, prices=None):
    """Create a brand-new product in the catalogue.

    Returns (ok, product_id_or_message). A new product has no row in the built-in
    range, so it is stored in shop_products with is_custom set and its pack sizes
    in their own table.
    """
    name, error = _clean_text(display_name, CATALOG_NAME_LIMIT, "Product name")
    if error:
        return False, error
    if not name:
        return False, "Give the product a name."
    if name.lower() in crm_product_names_taken():
        return False, f"“{name}” already exists in the catalogue."

    summary, error = _clean_text(summary, CATALOG_SUMMARY_LIMIT, "Description")
    if error:
        return False, error

    clean_sizes, error = _clean_pack_sizes(sizes)
    if error:
        return False, error

    if not _summary_fits(name, summary, clean_sizes):
        return False, ("That description is too long for WhatsApp once the product name and "
                       "unit sizes are included. Shorten it.")

    # The browse list is one WhatsApp list message, so the range has to fit.
    if len(shop_all_products()) >= CATALOG_MAX_PRODUCTS:
        return False, (f"The catalogue already has {CATALOG_MAX_PRODUCTS} products, which is "
                       f"WhatsApp's limit for one list. Remove one before adding another.")

    product_id = _slugify_product_id(name)
    if not product_id:
        return False, "That name cannot be used as a product reference."
    if any(product["id"] == product_id for product in shop_all_products()):
        product_id = f"{product_id}-{random.randint(100, 999)}"

    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO shop_products (product_id, display_name, summary, is_custom,
                                           position, updated_at)
                VALUES (%s, %s, %s, TRUE, %s, NOW())
            """, (product_id, name, summary,
                  len(shop_all_products())))
            for index, size in enumerate(clean_sizes):
                cursor.execute("""
                    INSERT INTO shop_product_sizes (product_id, pack_size, position)
                    VALUES (%s, %s, %s)
                    ON CONFLICT (product_id, pack_size) DO NOTHING
                """, (product_id, size, index))
            for price_row in (prices or []):
                size, raw_price = price_row
                if raw_price in (None, ""):
                    continue
                try:
                    price = round(float(raw_price), 2)
                except (TypeError, ValueError):
                    continue
                if price < 0 or size not in clean_sizes:
                    continue
                cursor.execute("""
                    INSERT INTO shop_product_prices (product_id, pack_size, price, updated_at)
                    VALUES (%s, %s, %s, NOW())
                    ON CONFLICT (product_id, pack_size) DO UPDATE
                    SET price = EXCLUDED.price, updated_at = NOW()
                """, (product_id, size, price))
            connection.commit()
        shop_refresh_catalog()
        return True, product_id
    except Exception as e:
        print(f"product add error: {e}")
        return False, "The product could not be saved just now."


def crm_delete_product(product_id, user=None):
    """Remove a product from the catalogue.

    Works for any product, including the ones seeded from the code defaults. A
    record is kept in shop_product_removed so the seeder does not restore it on
    the next worker start — a deletion has to be as durable as an edit.
    """
    try:
        ensure_shop_tables()
        catalog = _shop_catalog()
        known = (any(base["id"] == product_id for base in BRILLIANT_PRODUCTS)
                 or product_id in (catalog.get("names") or {})
                 or product_id in (catalog.get("sizes") or {})
                 or any(product["id"] == product_id
                        for product in (catalog.get("custom") or [])))
        with get_db() as (cursor, connection):
            cursor.execute("SELECT display_name, image_path FROM shop_products "
                           "WHERE product_id = %s", (product_id,))
            row = cursor.fetchone()
            name = (row[0] if row and row[0] else product_id)
            # Captured before the delete so the file can go with the row: the
            # picture has no other route back into the catalogue once its product
            # is gone, so leaving it would be an orphan nobody could clean up.
            stored_image = str(row[1]).strip() if row and len(row) > 1 and row[1] else ""
            if not row and not known:
                return False, "That product is no longer in the catalogue."
            # The tombstone is written before the delete so an interrupted run
            # cannot leave a product that is deleted but still seedable.
            cursor.execute("""
                INSERT INTO shop_product_removed (product_id, display_name, removed_by, removed_at)
                VALUES (%s, %s, %s, NOW())
                ON CONFLICT (product_id) DO UPDATE
                SET display_name = EXCLUDED.display_name,
                    removed_by = EXCLUDED.removed_by,
                    removed_at = NOW()
            """, (product_id, name,
                  f"{(user or {}).get('firstname', '')} {(user or {}).get('surname', '')}".strip()
                  or None))
            cursor.execute("DELETE FROM shop_product_prices WHERE product_id = %s", (product_id,))
            cursor.execute("DELETE FROM shop_product_sizes WHERE product_id = %s", (product_id,))
            cursor.execute("DELETE FROM shop_products WHERE product_id = %s", (product_id,))
            connection.commit()
        if stored_image:
            full = _product_image_absolute_path(stored_image)
            if full:
                try:
                    os.remove(full)
                except OSError as e:
                    # The row is gone, so the picture is unreachable either way.
                    print(f"product image delete error: {e}")
        shop_refresh_catalog()
        return True, ""
    except Exception as e:
        print(f"product delete error: {e}")
        return False, "The product could not be removed."


def crm_restore_product(product_id):
    """Undo a removal so the product can be seeded again.

    Returns (ok, message). Nothing is re-created here: clearing the record lets
    the seeder copy the code default back on the next read.
    """
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT product_id FROM shop_product_removed WHERE product_id = %s",
                           (product_id,))
            if cursor.fetchone() is None:
                return False, "That product has not been removed."
            cursor.execute("DELETE FROM shop_product_removed WHERE product_id = %s", (product_id,))
            connection.commit()
        # Let the seeder run again for this id.
        global _catalog_seeded
        _catalog_seeded = False
        shop_ensure_seeded()
        shop_refresh_catalog()
        return True, ""
    except Exception as e:
        print(f"product restore error: {e}")
        return False, "The product could not be restored."


def crm_removed_products():
    """Products removed from the catalogue, newest first."""
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                SELECT product_id, display_name, removed_by, removed_at
                FROM shop_product_removed ORDER BY removed_at DESC
            """)
            return [{"id": row[0], "name": row[1] or row[0], "removed_by": row[2] or "",
                     "removed_at": fmt_time(row[3], "%d %b %Y %H:%M")}
                    for row in cursor.fetchall()]
    except Exception as e:
        print(f"removed products error: {e}")
        return []


def crm_save_product(product_id, display_name=None, summary=None):
    """Rename a product and rewrite its customer-facing description.

    Names are validated against WhatsApp's list row limit because the name is
    what the customer's browse list shows.
    """
    name, error = _clean_text(display_name, CATALOG_NAME_LIMIT, "Product name")
    if error:
        return False, error
    summary, error = _clean_text(summary, CATALOG_SUMMARY_LIMIT, "Description")
    if error:
        return False, error

    built_in = any(base["id"] == product_id for base in BRILLIANT_PRODUCTS)
    if not built_in:
        if not any(product["id"] == product_id for product in shop_all_products()):
            return False, "That product is no longer in the catalogue."
        if not name:
            return False, "A product added here needs a name."

    if name and name.lower() in crm_product_names_taken(exclude_id=product_id):
        return False, f"“{name}” is already used by another product."

    # The description and the pack list share one WhatsApp message with the name,
    # so refuse a combination that would not fit together.
    current = next((product for product in shop_all_products()
                    if product["id"] == product_id), None)
    if current and not _summary_fits(name or current["name"], summary or "",
                                     current["sizes"]):
        return False, ("That description is too long for WhatsApp once the product name and "
                       "unit sizes are included. Shorten it.")

    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            if built_in:
                cursor.execute("""
                    INSERT INTO shop_products (product_id, display_name, summary, updated_at)
                    VALUES (%s, %s, %s, NOW())
                    ON CONFLICT (product_id) DO UPDATE
                    SET display_name = EXCLUDED.display_name, summary = EXCLUDED.summary,
                        updated_at = NOW()
                """, (product_id, name or None, summary or None))
            else:
                cursor.execute("""
                    UPDATE shop_products
                    SET display_name = %s, summary = %s, updated_at = NOW()
                    WHERE product_id = %s
                """, (name, summary, product_id))
            connection.commit()
        shop_refresh_catalog()
        return True, ""
    except Exception as e:
        print(f"catalog save error: {e}")
        return False, "The product could not be saved just now."


def crm_save_product_image(product_id, upload):
    """Store a product picture and point the catalogue at it. Returns (path, error).

    The file is written under the app's static folder with a name derived from
    the product id, so replacing a picture replaces the file rather than leaving
    the old one behind, and the stored path never has to be guessed at read time.
    """
    if not any(product["id"] == product_id for product in shop_all_products()):
        return "", "That product is no longer in the catalogue."
    if upload is None or not getattr(upload, "filename", ""):
        return "", "Choose an image file first."
    filename = str(upload.filename).strip()
    extension = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    if extension not in PRODUCT_IMAGE_EXTENSIONS:
        allowed = ", ".join(sorted(PRODUCT_IMAGE_EXTENSIONS))
        return "", f"That file type is not supported — use one of: {allowed}."
    # Read before writing so an oversized upload is refused without touching the
    # folder, and measure the bytes rather than trusting a Content-Length header.
    try:
        data = upload.read()
    except Exception as e:
        print(f"product image upload error: {e}")
        return "", "That file could not be read."
    if not data:
        return "", "That file is empty."
    if len(data) > PRODUCT_IMAGE_MAX_BYTES:
        limit = PRODUCT_IMAGE_MAX_BYTES // (1024 * 1024)
        return "", f"Images must be {limit} MB or smaller."
    # A product id is admin-supplied free text but is also used as a filename, so
    # it is reduced to characters that cannot climb out of the folder.
    safe_id = re.sub(r"[^A-Za-z0-9_-]+", "-", str(product_id)).strip("-") or "product"
    stored = f"{safe_id}.{extension}"
    folder = os.path.join(app.static_folder, PRODUCT_IMAGE_DIR)
    try:
        os.makedirs(folder, exist_ok=True)
        # The previous picture, whatever extension it used, goes first: a product
        # that switches from png to jpg would otherwise keep serving the old one.
        for existing in os.listdir(folder):
            if os.path.splitext(existing)[0] == safe_id and existing != stored:
                try:
                    os.remove(os.path.join(folder, existing))
                except OSError:
                    pass
        with open(os.path.join(folder, stored), "wb") as handle:
            handle.write(data)
    except Exception as e:
        print(f"product image save error: {e}")
        return "", "That image could not be saved."
    relative = f"{PRODUCT_IMAGE_DIR}/{stored}".replace(os.sep, "/")
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO shop_products (product_id, image_path, updated_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (product_id) DO UPDATE
                SET image_path = EXCLUDED.image_path, updated_at = NOW()
            """, (product_id, relative))
            connection.commit()
        shop_refresh_catalog()
        return relative, ""
    except Exception as e:
        print(f"product image save error: {e}")
        return "", "The image was stored but the catalogue could not be updated."


def crm_clear_product_image(product_id):
    """Remove a product's picture. Returns (ok, error)."""
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT image_path FROM shop_products WHERE product_id = %s",
                           (product_id,))
            row = cursor.fetchone()
            stored = str(row[0]).strip() if row and row[0] else ""
            cursor.execute("UPDATE shop_products SET image_path = NULL, updated_at = NOW() "
                           "WHERE product_id = %s", (product_id,))
            connection.commit()
        if stored:
            full = _product_image_absolute_path(stored)
            if full:
                try:
                    os.remove(full)
                except OSError as e:
                    # The catalogue no longer references it, so a file that will
                    # not delete is untidy rather than a failure.
                    print(f"product image delete error: {e}")
        shop_refresh_catalog()
        return True, ""
    except Exception as e:
        print(f"product image clear error: {e}")
        return False, "The image could not be removed just now."


def crm_save_company_logo(upload):
    """Store the company logo. Returns (path, error).

    Validated the same way a product picture is, with the reason stated rather
    than left to Meta or WeasyPrint to fail on later.
    """
    global _company_logo_cache
    if upload is None or not getattr(upload, "filename", ""):
        return "", "Choose a logo file first."
    filename = str(upload.filename).strip()
    extension = filename.rsplit(".", 1)[-1].lower() if "." in filename else ""
    if extension not in LOGO_EXTENSIONS:
        allowed = ", ".join(sorted(LOGO_EXTENSIONS))
        return "", f"That file type is not supported — use one of: {allowed}."
    try:
        data = upload.read()
    except Exception as e:
        print(f"logo upload error: {e}")
        return "", "That file could not be read."
    if not data:
        return "", "That file is empty."
    if len(data) > LOGO_MAX_BYTES:
        limit = LOGO_MAX_BYTES // (1024 * 1024)
        return "", f"The logo must be {limit} MB or smaller."
    stored = f"logo.{extension}"
    folder = os.path.join(app.static_folder, LOGO_DIR)
    try:
        os.makedirs(folder, exist_ok=True)
        # The previous logo goes first, whatever extension it used, so switching
        # from png to jpg cannot leave the old file serving alongside the new one.
        for existing in os.listdir(folder):
            if existing.startswith("logo.") and existing != stored:
                try:
                    os.remove(os.path.join(folder, existing))
                except OSError:
                    pass
        with open(os.path.join(folder, stored), "wb") as handle:
            handle.write(data)
    except Exception as e:
        print(f"logo save error: {e}")
        return "", "That logo could not be saved."
    relative = f"{LOGO_DIR}/{stored}".replace(os.sep, "/")
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("""
                INSERT INTO shop_branding (brand_key, logo_path, updated_at)
                VALUES (%s, %s, NOW())
                ON CONFLICT (brand_key) DO UPDATE
                SET logo_path = EXCLUDED.logo_path, updated_at = NOW()
            """, (LOGO_BRAND_KEY, relative))
            connection.commit()
        _company_logo_cache = {"loaded": True, "path": relative}
        return relative, ""
    except Exception as e:
        print(f"logo save error: {e}")
        return "", "The logo was stored but the setting could not be updated."


def crm_clear_company_logo():
    """Remove the company logo. Returns (ok, error)."""
    global _company_logo_cache
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("SELECT logo_path FROM shop_branding WHERE brand_key = %s",
                           (LOGO_BRAND_KEY,))
            row = cursor.fetchone()
            stored = str(row[0]).strip() if row and row[0] else ""
            cursor.execute("UPDATE shop_branding SET logo_path = NULL, updated_at = NOW() "
                           "WHERE brand_key = %s", (LOGO_BRAND_KEY,))
            connection.commit()
        if stored:
            full = _logo_absolute_path(stored)
            if full:
                try:
                    os.remove(full)
                except OSError as e:
                    # The row no longer references it, so this is untidiness
                    # rather than a failure worth reporting to the user.
                    print(f"logo delete error: {e}")
        _company_logo_cache = {"loaded": True, "path": ""}
        return True, ""
    except Exception as e:
        print(f"logo clear error: {e}")
        return False, "The logo could not be removed just now."


def crm_save_product_sizes(product_id, sizes):
    """Replace the pack sizes shown for a product.

    Works for the built-in range too: the sizes in code are only a starting
    point, and the portal is the place they are managed. Removing a size here
    removes it from what the assistant offers.
    """
    if not any(product["id"] == product_id for product in shop_all_products()):
        # An incomplete portal product may not be in the sellable range yet, so
        # check the stored rows as well.
        catalog = _shop_catalog()
        known = (any(base["id"] == product_id for base in BRILLIANT_PRODUCTS)
                 or any(product["id"] == product_id
                        for product in (catalog.get("custom") or [])))
        if not known:
            return False, "That product is no longer in the catalogue."
    clean_sizes, error = _clean_pack_sizes(sizes)
    if error:
        return False, error
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            cursor.execute("DELETE FROM shop_product_sizes WHERE product_id = %s", (product_id,))
            # Drop prices for any pack size that no longer exists.
            cursor.execute("""
                DELETE FROM shop_product_prices
                WHERE product_id = %s AND pack_size <> ALL(%s)
            """, (product_id, clean_sizes))
            for index, size in enumerate(clean_sizes):
                cursor.execute("""
                    INSERT INTO shop_product_sizes (product_id, pack_size, position)
                    VALUES (%s, %s, %s)
                """, (product_id, size, index))
            connection.commit()
        shop_refresh_catalog()
        return True, ""
    except Exception as e:
        print(f"size save error: {e}")
        return False, "The pack sizes could not be saved."


def crm_save_price(product_id, pack_size, price):
    """Set or clear the selling price of one pack size."""
    known = any(base["id"] == product_id and pack_size in base["sizes"]
                for base in BRILLIANT_PRODUCTS)
    if not known:
        known = any(product["id"] == product_id and pack_size in product["sizes"]
                    for product in shop_all_products())
    if not known:
        return False
    try:
        ensure_shop_tables()
        with get_db() as (cursor, connection):
            if price in (None, ""):
                cursor.execute("DELETE FROM shop_product_prices WHERE product_id = %s AND pack_size = %s",
                               (product_id, pack_size))
            else:
                cursor.execute("""
                    INSERT INTO shop_product_prices (product_id, pack_size, price, updated_at)
                    VALUES (%s, %s, %s, NOW())
                    ON CONFLICT (product_id, pack_size) DO UPDATE
                    SET price = EXCLUDED.price, updated_at = NOW()
                """, (product_id, pack_size, round(float(price), 2)))
            connection.commit()
        shop_refresh_catalog()
        return True
    except Exception as e:
        print(f"price save error: {e}")
        return False


