@app.route('/api/crm/activity.pdf')
def crm_activity_pdf():
    user, error = portal_api_user('crm')
    if error:
        return error
    period = request.args.get('period', 'today')
    date_from = (request.args.get('from') or '').strip() or None
    date_to = (request.args.get('to') or '').strip() or None
    category = request.args.get('category', 'all')
    employee = (request.args.get('employee') or '').strip() or None
    entries = activity_log_entries(period=period, category=category, employee=employee,
                                   date_from=date_from, date_to=date_to)
    if not entries:
        return jsonify({'success': False,
                        'message': 'There is nothing to export for that period.'}), 400
    html = render_template(
        'activity_log_pdf.html',
        entries=entries,
        period_label=activity_period_label(period, date_from, date_to),
        category_label=(AUDIT_CATEGORIES.get(category, 'All activity')
                        if category != 'all' else 'All activity'),
        employee_filter=employee or '',
        generated_by=f"{user.get('firstname', '')} {user.get('surname', '')}".strip(),
        generated_at=datetime.now().strftime('%d %B %Y, %H:%M'),
        company_name=COMPANY_SYSTEM_NAME,
        company_contact=COMPANY_SYSTEM_CONTACT,
    )
    try:
        pdf = HTML(string=html).write_pdf()
    except Exception as e:
        print(f"activity pdf error: {e}")
        return jsonify({'success': False, 'message': 'Could not build the PDF.'}), 500
    stamp = datetime.now().strftime('%Y%m%d-%H%M')
    response = make_response(pdf)
    response.headers['Content-Type'] = 'application/pdf'
    response.headers['Content-Disposition'] = \
        f'attachment; filename=brilliant_chemicals_activity_log_{stamp}.pdf'
    return response


# ------------------------------------------------- orders, documents, payment --
def _pdf_download(html, filename):
    """Render HTML to a PDF download, or a JSON error the portal can show."""
    try:
        pdf = HTML(string=html).write_pdf()
    except Exception as e:
        print(f"pdf build error ({filename}): {e}")
        return jsonify({'success': False, 'message': 'Could not build the PDF.'}), 500
    response = make_response(pdf)
    response.headers['Content-Type'] = 'application/pdf'
    response.headers['Content-Disposition'] = f'attachment; filename={filename}'
    return response


def _order_document_context(order, user):
    """Values shared by both printed documents."""
    method_key = _shop_payment_method(order.get('payment_method'))
    return {
        'order': order,
        # Both documents name how the money moved, from the one vocabulary, so a
        # printed receipt cannot describe a payment differently to the chatbot.
        'payment_method_key': method_key,
        'payment_method_label': SHOP_PAYMENT_METHOD_LABELS.get(method_key, ''),
        'printed_at': local_time(datetime.utcnow()).strftime('%d %b %Y %H:%M'),
        'printed_by': f"{user.get('firstname', '')} {user.get('surname', '')}".strip(),
        'company_name': COMPANY_SYSTEM_NAME,
        'company_contact': COMPANY_SYSTEM_CONTACT,
        # Embedded as a data URI rather than linked: the PDF travels once it is
        # rendered, and a link would need the file to stay fetchable from
        # wherever the customer later opens it.
        'company_logo': company_logo_data_uri(),
    }


